               >
                   <Plus size={16} /> Add Keyframe at {new Date(currentTime * 1000).toISOString().substr(14, 5)}
               </button>

               <div className="flex-1 overflow-y-auto space-y-2 mb-4">
                  {(config.keyframes || []).length === 0 ? (
                      <div className="text-center text-gray-600 text-xs mt-10">
                          No keyframes.<br/>Values are static.
                      </div>
                  ) : (
                      (config.keyframes || []).map((kf, idx) => (
                          <div 
                              key={kf.id}
                              onClick={() => setSelectedKeyframeId(kf.id)}
                              className={`p-3 rounded-lg border flex items-center justify-between cursor-pointer transition-colors ${selectedKeyframeId === kf.id ? 'bg-cyan-900/30 border-cyan-500/50' : 'bg-neutral-900 border-white/5 hover:border-white/20'}`}
                          >
                              <div className="flex flex-col">
                                  <span className="font-mono font-bold text-xs text-gray-300">Keyframe {idx + 1}</span>
                                  <span className="text-[10px] text-gray-500">{new Date(kf.time * 1000).toISOString().substr(14, 5)}s</span>
                              </div>
                          </div>
                      ))
                  )}
               </div>

               {selectedKeyframe && (
                   <KeyframeEditor 
                      keyframe={selectedKeyframe} 
                      defaults={config} 
                      onUpdate={updateKeyframe} 
                      onDelete={deleteKeyframe}
                   />
               )}
           </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { DEFAULT_LYRICS, TEMPLATES, RESOLUTIONS } from './constants';
import { CanvasVideoRenderer, CanvasVideoRendererRef } from './components/CanvasVideoRenderer';
import { Controls } from './components/Controls';
import { SettingsPanel } from './components/SettingsPanel';
import { LyricData, RenderStatus, AudioVisualizerData, Segment, Word, RendererConfig, ProjectFile, AudioLayer } from './types';
import { Save, FolderOpen, Activity, Loader2, Video, Download, RotateCcw, Check, Zap, Trash2, FileVideo } from 'lucide-react';

// @ts-ignore
import { Muxer as WebMMuxer, ArrayBufferTarget as WebMArrayBufferTarget } from 'webm-muxer';
// @ts-ignore
import { Muxer as Mp4Muxer, ArrayBufferTarget as Mp4ArrayBufferTarget } from 'mp4-muxer';

// Declarations for missing WebCodecs types to satisfy TypeScript
declare class AudioEncoder {
  constructor(init: { output: (chunk: any, meta: any) => void; error: (e: any) => void });
  configure(config: any): void;
  encode(data: any): void;
  flush(): Promise<void>;
  close(): void;
}

declare class AudioData {
  constructor(init: any);
  close(): void;
}

// Helper to parse SRT timestamp "00:00:12,345" or "00:00:12.345" to seconds
const parseSrtTimestamp = (timestamp: string): number => {
  if (!timestamp) return 0;
  // Normalize comma to dot and trim
  const normalized = timestamp.replace(',', '.').trim();
  const parts = normalized.split(':');

  if (parts.length < 3) return 0; 

  const hours = parseFloat(parts[0]);
  const minutes = parseFloat(parts[1]);
  const seconds = parseFloat(parts[2]);

  return (hours * 3600) + (minutes * 60) + seconds;
};

// Helper to parse SRT string to LyricData
const parseSrtToLyricData = (srtContent: string): LyricData => {
  const normalizedContent = srtContent.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  const blocks = normalizedContent.trim().split(/\n\s*\n/);

  const segments: Segment[] = [];

  blocks.forEach((block, index) => {
    const lines = block.split('\n');
    if (lines.length < 2) return;

    let timeLineIndex = lines.findIndex(l => l.includes('-->'));
    if (timeLineIndex === -1) return;

    const timeLine = lines[timeLineIndex];
    const [startStr, endStr] = timeLine.split('-->');

    if (!startStr || !endStr) return;

    const start = parseSrtTimestamp(startStr);
    const end = parseSrtTimestamp(endStr);

    // Extract text (lines after timestamp)
    // Remove HTML tags often found in SRTs
    const textLines = lines.slice(timeLineIndex + 1)
        .map(l => l.replace(/<[^>]*>/g, '').trim())
        .filter(l => l.length > 0);

    const fullText = textLines.join(' ');
    if (!fullText) return;

    // Create words with estimated timing
    const words: Word[] = [];
    const totalDuration = end - start;

    // Flatten words while keeping track of line numbers
    let allWords: {text: string, line: number}[] = [];
    textLines.forEach((line, lineIdx) => {
        const lineWords = line.split(/\s+/);
        lineWords.forEach(w => allWords.push({ text: w, line: lineIdx }));
    });

    const wordDuration = totalDuration / allWords.length;

    allWords.forEach((wObj, i) => {
      words.push({
        word: wObj.text,
        start: start + (i * wordDuration),
        end: start + ((i + 1) * wordDuration),
        probability: 1.0,
        line_number: wObj.line
      });
    });

    segments.push({
      id: index.toString(),
      start,
      end,
      text: fullText,
      section: 'verse',
      words
    });
  });

  return { segments };
};

export default function App() {
  const [data, setData] = useState<LyricData>(DEFAULT_LYRICS);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);

  // Multi-track State
  const [audioLayers, setAudioLayers] = useState<AudioLayer[]>([]);

  const [renderStatus, setRenderStatus] = useState<RenderStatus>({ state: 'idle', progress: 0 });
  const [audioVisualizerData, setAudioVisualizerData] = useState<AudioVisualizerData>({ bass: 0, mid: 0, high: 0, raw: new Uint8Array() });

  const [rendererConfig, setRendererConfig] = useState<RendererConfig>(TEMPLATES[0]);
  const [exportFormat, setExportFormat] = useState<'webm' | 'mp4'>('mp4');
  const [exportMode, setExportMode] = useState<'normal' | 'alpha'>('normal');

  const [lastSaved, setLastSaved] = useState<Date | null>(null);

  // Caching / Instant Export State
  const [cachedBlob, setCachedBlob] = useState<Blob | null>(null);
  const [isCaching, setIsCaching] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);
  const audioDestinationRef = useRef<MediaStreamAudioDestinationNode | null>(null);

  // Web Audio Context Refs
  const audioContextRef = useRef<AudioContext | null>(null);
  const masterGainRef = useRef<GainNode | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const sourcesRef = useRef<Map<string, AudioBufferSourceNode>>(new Map());
  const gainsRef = useRef<Map<string, GainNode>>(new Map());

  const rendererRef = useRef<CanvasVideoRendererRef>(null);
  const requestRef = useRef<number>(0);
  const startTimeRef = useRef<number>(0);

  // Initialize Audio Engine
  const initAudioEngine = () => {
      if (!audioContextRef.current) {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          const ctx = new AudioContext();
          audioContextRef.current = ctx;

          // Master Gain
          const masterGain = ctx.createGain();
          masterGain.connect(ctx.destination);
          masterGainRef.current = masterGain;

          // Setup MediaStream Destination for Recording
          const dest = ctx.createMediaStreamDestination();
          masterGain.connect(dest);
          audioDestinationRef.current = dest;

          // Analyser
          const analyser = ctx.createAnalyser();
          analyser.fftSize = 256;
          masterGain.connect(analyser); // Master -> Analyser
          analyserRef.current = analyser;
      } else if (audioContextRef.current.state === 'suspended') {
          audioContextRef.current.resume();
      }
  };

  // Invalidate cache if PROJECT changes
  useEffect(() => {
    if (cachedBlob) {
        console.log("Project changed, invalidating cache...");
        setCachedBlob(null);
    }
  }, [data, rendererConfig, audioLayers]);

  // Auto-Load Project
  useEffect(() => {
    try {
      const saved = localStorage.getItem('kinetic-flow-autosave');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (parsed.lyricData) setData(parsed.lyricData);
        if (parsed.config) {
             const loadedConfig = parsed.config;
             // Handle expired blob URLs
             if ((loadedConfig.background.type === 'image' || loadedConfig.background.type === 'video') && 
                  loadedConfig.background.url?.startsWith('blob:')) {
                  loadedConfig.background.type = 'solid';
                  loadedConfig.background.url = undefined;
             }
             setRendererConfig(loadedConfig);
        }
        if (parsed.timestamp) setLastSaved(new Date(parsed.timestamp));
      }
    } catch (e) {
      console.error("Autosave load failed", e);
    }
  }, []);

  // Auto-Save Project
  useEffect(() => {
    const timer = setTimeout(() => {
      const saveState = {
        version: '1.0',
        timestamp: Date.now(),
        lyricData: data,
        config: rendererConfig
      };
      localStorage.setItem('kinetic-flow-autosave', JSON.stringify(saveState));
      setLastSaved(new Date());
    }, 2000); // 2 second debounce

    return () => clearTimeout(timer);
  }, [data, rendererConfig]);

  const handleResetProject = () => {
    if (confirm("Are you sure you want to reset the project? This will clear all changes and local cache.")) {
       localStorage.removeItem('kinetic-flow-autosave');
       setData(DEFAULT_LYRICS);
       setRendererConfig(TEMPLATES[0]);
       setAudioLayers([]);
       setLastSaved(null);
       setCachedBlob(null);
    }
  };

  // Handle Layer Upload
  const handleAudioLayerAdd = async (file: File) => {
      initAudioEngine();
      if (!audioContextRef.current) return;

      try {
          const arrayBuffer = await file.arrayBuffer();
          const audioBuffer = await audioContextRef.current.decodeAudioData(arrayBuffer);

          const newLayer: AudioLayer = {
              id: Date.now().toString() + Math.random().toString(),
              name: file.name,
              buffer: audioBuffer,
              volume: 1.0,
              muted: false,
              solo: false,
              duration: audioBuffer.duration
          };

          setAudioLayers(prev => {
              const updated = [...prev, newLayer];
              const maxDur = Math.max(...updated.map(l => l.duration));
              setDuration(maxDur);
              return updated;
          });
      } catch (e) {
          console.error("Error decoding audio", e);
          alert("Failed to load audio file.");
      }
  };

  const updateLayer = (id: string, updates: Partial<AudioLayer>) => {
      setAudioLayers(prev => prev.map(l => {
          if (l.id === id) return { ...l, ...updates };
          return l;
      }));
  };

  const removeLayer = (id: string) => {
      setAudioLayers(prev => {
          const updated = prev.filter(l => l.id !== id);
          const maxDur = Math.max(...updated.map(l => l.duration), 0);
          setDuration(maxDur);
          return updated;
      });
  };

  // Sync Audio Nodes with React State
  useEffect(() => {
     if (!audioContextRef.current) return;

     const hasSolo = audioLayers.some(l => l.solo);

     audioLayers.forEach(layer => {
         if (!gainsRef.current.has(layer.id)) {
             const g = audioContextRef.current!.createGain();
             if (masterGainRef.current) g.connect(masterGainRef.current);
             gainsRef.current.set(layer.id, g);
         }

         const gainNode = gainsRef.current.get(layer.id);
         if (gainNode) {
             const effectiveMute = layer.muted || (hasSolo && !layer.solo);
             const currentTime = audioContextRef.current!.currentTime;
             gainNode.gain.cancelScheduledValues(currentTime);
             gainNode.gain.setTargetAtTime(effectiveMute ? 0 : layer.volume, currentTime, 0.05);
         }
     });

     gainsRef.current.forEach((val, key) => {
         if (!audioLayers.find(l => l.id === key)) {
             val.disconnect();
             gainsRef.current.delete(key);
         }
     });

  }, [audioLayers]);


  const stopAllSources = () => {
      sourcesRef.current.forEach(source => {
          try { source.stop(); } catch(e) {}
          source.disconnect();
      });
      sourcesRef.current.clear();
  };

  const startAllSources = (offset: number) => {
      if (!audioContextRef.current) return;
      stopAllSources();

      audioLayers.forEach(layer => {
          const source = audioContextRef.current!.createBufferSource();
          source.buffer = layer.buffer;

          const gainNode = gainsRef.current.get(layer.id);
          if (gainNode) {
              source.connect(gainNode);
          }

          source.start(0, offset);
          sourcesRef.current.set(layer.id, source);
      });
  };

  // --- SMART CACHING LOGIC ---
  const startRecordingCache = () => {
      if (!rendererRef.current?.canvas || !audioDestinationRef.current) return;

      try {
          // 1. Capture Canvas Stream (60fps preferred for smoothness)
          const canvasStream = rendererRef.current.canvas.captureStream(60);

          // 2. Capture Audio Stream
          const audioStream = audioDestinationRef.current.stream;

          // 3. Combine tracks
          const combinedTracks = [
              ...canvasStream.getVideoTracks(),
              ...audioStream.getAudioTracks()
          ];
          const combinedStream = new MediaStream(combinedTracks);

          // 4. Initialize Recorder
          // Prefer higher bitrate for "Cached" quality
          const options: MediaRecorderOptions = {
              mimeType: MediaRecorder.isTypeSupported('video/webm;codecs=vp9') ? 'video/webm;codecs=vp9' : 'video/webm',
              videoBitsPerSecond: 8000000 // 8 Mbps
          };

          const recorder = new MediaRecorder(combinedStream, options);
          recordedChunksRef.current = [];

          recorder.ondataavailable = (e) => {
              if (e.data.size > 0) {
                  recordedChunksRef.current.push(e.data);
              }
          };

          recorder.onstop = () => {
              // Only save if we stopped intentionally (end of song) not interrupted
              // Logic is handled in loop or handleSeek
          };

          recorder.start();
          mediaRecorderRef.current = recorder;
          setIsCaching(true);
          console.log("Started caching playback...");
      } catch (err) {
          console.error("Failed to start caching", err);
      }
  };

  const stopRecordingCache = (save: boolean) => {
      if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
          mediaRecorderRef.current.stop();

          if (save && recordedChunksRef.current.length > 0) {
               const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' });
               setCachedBlob(blob);
               console.log("Caching complete. Blob created size:", blob.size);
          } else {
              console.log("Caching discarded.");
          }
      }
      setIsCaching(false);
      mediaRecorderRef.current = null;
  };

  const togglePlay = () => {
    initAudioEngine();
    if (!audioContextRef.current) return;

    if (isPlaying) {
      // Pause
      // If we were caching, this invalidates the "perfect run", so discard.
      if (isCaching) stopRecordingCache(false);

      audioContextRef.current.suspend();
      setIsPlaying(false);
    } else {
      // Play
      audioContextRef.current.resume();

      // If sources aren't running
      if (sourcesRef.current.size === 0) {
          // If starting from the very beginning, try to cache this run
          if (currentTime < 0.1) {
              // Clear old cache
              setCachedBlob(null); 
              startRecordingCache();
          }

          startAllSources(currentTime);
          startTimeRef.current = audioContextRef.current.currentTime - currentTime;
      }
      setIsPlaying(true);
    }
  };

  const handleSeek = (time: number) => {
      if (!audioContextRef.current) return;

      // Seeking invalidates current recording run
      if (isCaching) stopRecordingCache(false);

      const wasPlaying = isPlaying;
      audioContextRef.current.suspend();
      stopAllSources();

      setCurrentTime(time);
      startTimeRef.current = audioContextRef.current.currentTime - time;

      if (wasPlaying) {
          startAllSources(time);
          audioContextRef.current.resume();
      }
  };

  const analyzeAudio = () => {
    if (analyserRef.current) {
      const bufferLength = analyserRef.current.frequencyBinCount;
      const dataArray = new Uint8Array(bufferLength);
      analyserRef.current.getByteFrequencyData(dataArray);

      const bassRange = dataArray.slice(0, 10);
      const midRange = dataArray.slice(10, 100);
      const highRange = dataArray.slice(100, 200);

      const avg = (arr: Uint8Array) => arr.reduce((a, b) => a + b, 0) / arr.length;

      setAudioVisualizerData({
        bass: avg(bassRange) / 255,
        mid: avg(midRange) / 255,
        high: avg(highRange) / 255,
        raw: dataArray
      });
    }
  };

  const loop = () => {
    if (isPlaying && audioContextRef.current) {
        const now = audioContextRef.current.currentTime;
        let syncedTime = now - startTimeRef.current;

        if (syncedTime >= duration && duration > 0) {
            syncedTime = duration;

            // If we reached the end AND we were caching, save it!
            if (isCaching) {
                stopRecordingCache(true);
            }

            setIsPlaying(false);
            stopAllSources();
            audioContextRef.current.suspend();
        }

        setCurrentTime(syncedTime);
        analyzeAudio();
    }

    if (rendererRef.current) {
        // Playback render mode is always normal (not alpha)
        rendererRef.current.drawFrame(currentTime, audioVisualizerData, false);
    }

    requestRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [currentTime, audioVisualizerData, isPlaying, duration, isCaching]);


  const handleJsonUpload = (jsonStr: string) => {
    try {
      const parsed = JSON.parse(jsonStr);
      if (parsed.segments) setData(parsed);
    } catch (e) {
      alert("Error parsing JSON");
    }
  };

  const handleSrtUpload = (srtStr: string) => {
    try {
        const parsed = parseSrtToLyricData(srtStr);
        if (parsed.segments.length > 0) setData(parsed);
    } catch (e) {
        alert("Error parsing SRT");
    }
  };

  const handleSaveProject = () => {
      const project: ProjectFile = {
          version: '1.0',
          timestamp: Date.now(),
          name: audioLayers.length > 0 ? audioLayers[0].name : 'Untitled Project',
          lyricData: data,
          config: rendererConfig
      };

      const blob = new Blob([JSON.stringify(project, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `kinetic-project-${Date.now()}.json`;
      a.click();
      URL.revokeObjectURL(url);
  };

  const handleLoadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (ev) => {
          try {
              if (ev.target?.result) {
                  const project = JSON.parse(ev.target.result as string) as ProjectFile;
                  if (project.lyricData && project.config) {
                      setData(project.lyricData);
                      setRendererConfig(project.config);
                      setCachedBlob(null); // Clear cache on load
                      alert("Project loaded! Please re-add your audio layers.");
                  }
              }
          } catch(err) {
              alert("Failed to parse project file.");
          }
      };
      reader.readAsText(file);
  };

  const downloadCachedVideo = () => {
      if (!cachedBlob) return;
      const url = URL.createObjectURL(cachedBlob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `kinetic-lyric-video-quick.${cachedBlob.type.includes('mp4') ? 'mp4' : 'webm'}`;
      a.click();
      URL.revokeObjectURL(url);
  };

  // --- HIGH STABILITY RENDERING ENGINE ---
  const startRendering = async () => {
    if (audioLayers.length === 0) {
      alert("Please add at least one audio layer.");
      return;
    }

    // Check if we can just use cache (ONLY for Normal export)
    if (cachedBlob && exportMode === 'normal') {
        if (confirm("A cached version from your playback is available! \n\nDo you want to download it instantly (Instant) or render a high-quality version frame-by-frame (Slow)?\n\nClick OK for Instant, Cancel for Slow Render.")) {
            downloadCachedVideo();
            return;
        }
    }

    if (renderStatus.state !== 'idle') return;

    const resConfig = RESOLUTIONS.find(r => r.id === rendererConfig.resolutionId) || RESOLUTIONS[0];
    const VIDEO_WIDTH = resConfig.width;
    const VIDEO_HEIGHT = resConfig.height;

    setRenderStatus({ state: 'analyzing', progress: 0 });

    // Stop live playback to free resources
    if (isPlaying && audioContextRef.current) {
        audioContextRef.current.suspend();
        setIsPlaying(false);
    }

    try {
      const sampleRate = 44100;
      const FPS = 30;
      const totalFrames = Math.ceil(duration * FPS);

      // PHASE 1: AUDIO RENDER & ANALYSIS (Fast, Offline)
      console.log("Phase 1: Rendering Audio & Extracting Analysis...");

      const offlineCtx = new OfflineAudioContext(2, Math.ceil(duration * sampleRate), sampleRate);
      const offlineMasterGain = offlineCtx.createGain();
      offlineMasterGain.connect(offlineCtx.destination);

      const offlineAnalyser = offlineCtx.createAnalyser();
      offlineAnalyser.fftSize = 256;
      offlineMasterGain.connect(offlineAnalyser);

      const hasSolo = audioLayers.some(l => l.solo);

      // Set up Audio Graph in Offline Context
      audioLayers.forEach(layer => {
           const effectiveMute = layer.muted || (hasSolo && !layer.solo);
           if (effectiveMute) return;

           const source = offlineCtx.createBufferSource();
           source.buffer = layer.buffer;

           const gain = offlineCtx.createGain();
           gain.gain.value = layer.volume;

           source.connect(gain);
           gain.connect(offlineMasterGain);
           source.start(0);
      });

      // Prepare Array to hold FFT data for every frame
      const analysisFrames: AudioVisualizerData[] = new Array(totalFrames);
      const dataArray = new Uint8Array(offlineAnalyser.frequencyBinCount);
      const frameDuration = 1 / FPS;

      // Schedule Suspend for every frame to grab FFT data
      for (let i = 0; i < totalFrames; i++) {
           const t = i * frameDuration;

           // Safety: Do not schedule suspend past duration
           if (t >= duration) break;

           offlineCtx.suspend(t).then(async () => {
               offlineAnalyser.getByteFrequencyData(dataArray);
               const bass = dataArray.slice(0, 10).reduce((a,b)=>a+b,0) / 10 / 255;
               const mid = dataArray.slice(10, 100).reduce((a,b)=>a+b,0) / 90 / 255;
               const high = dataArray.slice(100, 200).reduce((a,b)=>a+b,0) / 100 / 255;

               analysisFrames[i] = {
                   bass, mid, high,
                   raw: new Uint8Array(dataArray) // Copy buffer
               };
               // IMPORTANT: Must resume to continue to next suspend point
               await offlineCtx.resume();
           }).catch((e) => console.error("Suspend error", e));
      }

      // Execute Audio Rendering
      const renderedAudioBuffer = await offlineCtx.startRendering();
      console.log("Phase 1 Complete. Audio rendered.");

      // PHASE 2: VIDEO ENCODING (Batched, Backpressure Managed)
      setRenderStatus({ state: 'rendering', progress: 0, totalFrames });

      // FORCE WEBM FOR ALPHA EXPORT
      const finalExportFormat = exportMode === 'alpha' ? 'webm' : exportFormat;

      let muxer: any;
      if (finalExportFormat === 'mp4') {
        muxer = new Mp4Muxer({
            target: new Mp4ArrayBufferTarget(),
            video: { codec: 'avc', width: VIDEO_WIDTH, height: VIDEO_HEIGHT },
            audio: { codec: 'aac', numberOfChannels: 2, sampleRate: sampleRate },
            fastStart: false 
        });
      } else {
        // WEBM
        muxer = new WebMMuxer({
            target: new WebMArrayBufferTarget(),
            video: { 
                codec: 'V_VP9', 
                width: VIDEO_WIDTH, 
                height: VIDEO_HEIGHT, 
                frameRate: FPS,
                alpha: exportMode === 'alpha' // ENABLE ALPHA IN MUXER
            },
            audio: { codec: 'A_OPUS', numberOfChannels: 2, sampleRate: sampleRate }
        });
      }

      // Track encoder errors to stop the loop
      let encoderError: Error | null = null;

      const videoEncoder = new VideoEncoder({
        output: (chunk, meta) => muxer.addVideoChunk(chunk, meta),
        error: (e) => {
            encoderError = e;
            console.error("VideoEncoder error:", e);
        }
      });

      const codecConfig: VideoEncoderConfig = finalExportFormat === 'mp4' 
      ? { codec: 'avc1.4d002a', width: VIDEO_WIDTH, height: VIDEO_HEIGHT, bitrate: 8_000_000 } // Higher bitrate
      : { 
          codec: 'vp09.00.10.08', 
          width: VIDEO_WIDTH, 
          height: VIDEO_HEIGHT, 
          bitrate: 6_000_000,
          bitrateMode: exportMode === 'alpha' ? 'variable' : undefined, // Variable can help with alpha in some profiles
          alpha: exportMode === 'alpha' ? 'keep' : 'discard' // ENABLE ALPHA IN ENCODER
        };

      try {
          videoEncoder.configure(codecConfig);
      } catch (e) {
          console.error("Encoder Configuration Failed:", e);
          alert("Your browser does not support the selected export format (likely Alpha transparency). Please switch to 'Normal' mode.");
          setRenderStatus({ state: 'idle', progress: 0 });
          return;
      }

      const canvas = rendererRef.current?.canvas;
      if (!canvas) throw new Error("Canvas not found");

      // BATCH RENDERING LOOP
      const BATCH_SIZE = 10; // Process frames in small batches to keep UI alive

      for (let i = 0; i < totalFrames; i++) {
         if (encoderError) {
             throw new Error(`Encoding failed: ${encoderError.message || 'Unknown error'}`);
         }

         const time = i * frameDuration;
         const analysis = analysisFrames[i] || { bass: 0, mid: 0, high: 0, raw: new Uint8Array() };

         // WAIT FOR VIDEO SEEK (Fixes background video flickering)
         if (rendererRef.current?.seekToTime) {
             await rendererRef.current.seekToTime(time);
         }

         // Draw Frame with Alpha Support
         rendererRef.current?.drawFrame(time, analysis, exportMode === 'alpha');

         // Create VideoFrame from Canvas
         // If alpha, ensure context was created with alpha: true (it is in CanvasVideoRenderer)
         const frame = new VideoFrame(canvas, { 
             timestamp: time * 1_000_000,
             alpha: exportMode === 'alpha' ? 'keep' : 'discard' 
         });

         const keyFrame = i % (FPS * 2) === 0; // Keyframe every 2 seconds

         // Backpressure: If queue is full, wait for it to drain
         if (videoEncoder.encodeQueueSize > 5) {
             await videoEncoder.flush();
         }

         try {
             videoEncoder.encode(frame, { keyFrame });
         } catch (e) {
             frame.close();
             // Check if it's because of a previous error
             if (encoderError) throw new Error("Encoder closed unexpectedly.");
             throw e;
         }

         frame.close(); // Important: Release GPU memory immediately

         // Update UI & Yield to Event Loop every batch
         if (i % BATCH_SIZE === 0) {
             setRenderStatus(prev => ({ ...prev, progress: i }));
             await new Promise(resolve => setTimeout(resolve, 0)); // Yield to main thread
         }
      }

      setRenderStatus(prev => ({ ...prev, progress: totalFrames }));

      // PHASE 3: FINALIZE
      setRenderStatus({ state: 'encoding', progress: 100, totalFrames });
      await videoEncoder.flush();
      videoEncoder.close();

      // Audio Encoding (Skip for Alpha? No, usually keep audio)
      const audioEncoder = new AudioEncoder({
        output: (chunk, meta) => muxer.addAudioChunk(chunk, meta),
        error: (e) => console.error("AudioEncoder error:", e)
      });

      const audioCodecString = finalExportFormat === 'mp4' ? 'mp4a.40.2' : 'opus';
      audioEncoder.configure({
        codec: audioCodecString,
        numberOfChannels: 2,
        sampleRate: sampleRate,
        bitrate: 192000
      });

      // Interleave Audio Data
      const numberOfFrames = renderedAudioBuffer.length;
      const numberOfChannels = renderedAudioBuffer.numberOfChannels;
      const interleaved = new Float32Array(numberOfFrames * numberOfChannels);

      // Safe channel getters
      const channel0 = renderedAudioBuffer.getChannelData(0);
      const channel1 = numberOfChannels > 1 ? renderedAudioBuffer.getChannelData(1) : channel0;

      for(let i=0; i<numberOfFrames; i++) {
          interleaved[i*2] = channel0[i];
          interleaved[i*2+1] = channel1[i];
      }

      const audioData = new AudioData({
        format: 'f32',
        sampleRate: sampleRate,
        numberOfFrames: numberOfFrames,
        numberOfChannels: numberOfChannels,
        timestamp: 0,
        data: interleaved
      });

      audioEncoder.encode(audioData);
      await audioEncoder.flush();
      audioEncoder.close();

      // Finalize Muxer
      muxer.finalize();
      const { buffer } = muxer.target;
      const blob = new Blob([buffer], { type: finalExportFormat === 'mp4' ? 'video/mp4' : 'video/webm' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `kinetic-lyric-video${exportMode === 'alpha' ? '-alpha' : ''}.${finalExportFormat}`;
      a.click();

      setRenderStatus({ state: 'done', progress: 100 });
      setTimeout(() => setRenderStatus({ state: 'idle', progress: 0 }), 3000);

    } catch (e) {
      console.error("Export failed", e);
      // More friendly error for alpha issue
      if (exportMode === 'alpha' && (e as any)?.message?.includes('Alpha')) {
          alert("Export Failed: Your browser doesn't support transparent video encoding. Please switch 'ALPHA' to 'NORMAL' and try again.");
      } else {
          alert(`Rendering failed: ${(e as any)?.message || 'Unknown error'}`);
      }
      setRenderStatus({ state: 'idle', progress: 0 });
    }
  };

  const viewportResolution = RESOLUTIONS.find(r => r.id === rendererConfig.resolutionId) || RESOLUTIONS[0];
  const aspectRatio = viewportResolution.width / viewportResolution.height;

  return (
    <div className="h-screen w-screen flex flex-col bg-neutral-950 text-white overflow-hidden font-sans">

      {/* HEADER */}
      <header className="h-14 border-b border-white/10 flex items-center justify-between px-4 bg-neutral-900 shrink-0 z-20">
        <div className="flex items-center gap-2">
           <Activity className="text-cyan-400" />
           <h1 className="font-black tracking-tighter text-lg">KINETIC<span className="text-cyan-400">FLOW</span></h1>
        </div>

        {/* Center: Status Indicators */}
        <div className="flex items-center gap-4">
             {isCaching && (
                 <div className="flex items-center gap-1.5 bg-red-950/50 border border-red-500/30 px-2 py-0.5 rounded-full animate-pulse">
                     <div className="w-2 h-2 rounded-full bg-red-500" />
                     <span className="text-[10px] text-red-200 font-bold uppercase tracking-wide">Caching for Export</span>
                 </div>
             )}

             {cachedBlob && !isCaching && (
                 <div className="flex items-center gap-1.5 bg-green-950/50 border border-green-500/30 px-2 py-0.5 rounded-full">
                     <Zap size={10} className="text-green-400 fill-current" />
                     <span className="text-[10px] text-green-200 font-bold uppercase tracking-wide">Instant Export Ready</span>
                 </div>
             )}
        </div>

        <div className="flex items-center gap-2">
             {lastSaved && (
                <div className="text-[10px] text-gray-500 mr-2 flex items-center gap-1 animate-in fade-in duration-500">
                    <Check size={10} className="text-green-500"/>
                    <span className="hidden md:inline">Saved {lastSaved.toLocaleTimeString()}</span>
                </div>
             )}

             <div className="flex items-center bg-neutral-800 rounded-md border border-white/5 mr-4">
                  <button 
                    onClick={handleResetProject}
                    title="Reset Project"
                    className="p-2 hover:bg-neutral-700 text-gray-400 hover:text-red-400 transition-colors border-r border-white/5"
                  >
                      <RotateCcw size={18} />
                  </button>
                  <button 
                    onClick={handleSaveProject}
                    title="Save Project"
                    className="p-2 hover:bg-neutral-700 text-gray-400 hover:text-cyan-400 transition-colors border-r border-white/5"
                  >
                      <Save size={18} />
                  </button>
                  <label 
                    title="Load Project"
                    className="p-2 hover:bg-neutral-700 text-gray-400 hover:text-cyan-400 transition-colors cursor-pointer"
                  >
                      <FolderOpen size={18} />
                      <input type="file" accept=".json" onChange={handleLoadProject} className="hidden"/>
                  </label>
             </div>

             <div className="flex items-center gap-2 bg-neutral-800 p-1 rounded-md border border-white/5">
                 <div className="flex items-center px-1 border-r border-white/5 mr-1">
                     <button
                        onClick={() => setExportMode('normal')}
                        className={`text-[10px] px-2 py-1 font-bold rounded ${exportMode === 'normal' ? 'bg-neutral-600 text-white' : 'text-gray-400 hover:text-white'}`}
                     >
                        NORMAL
                     </button>
                     <button
                        onClick={() => setExportMode('alpha')}
                        className={`text-[10px] px-2 py-1 font-bold rounded flex items-center gap-1 ${exportMode === 'alpha' ? 'bg-neutral-600 text-white' : 'text-gray-400 hover:text-white'}`}
                        title="Transparent Background (WEBM)"
                     >
                        ALPHA
                     </button>
                 </div>

                 {!cachedBlob && exportMode === 'normal' && (
                    <select 
                        value={exportFormat}
                        onChange={(e) => setExportFormat(e.target.value as any)}
                        className="bg-transparent text-xs font-bold text-gray-300 outline-none px-2 py-1"
                        disabled={renderStatus.state !== 'idle'}
                        >
                        <option value="mp4">MP4</option>
                        <option value="webm">WEBM</option>
                    </select>
                 )}
                 <button
                    onClick={startRendering}
                    disabled={renderStatus.state !== 'idle' || audioLayers.length === 0}
                    className={`${cachedBlob && exportMode === 'normal' ? 'bg-green-600 hover:bg-green-500' : 'bg-cyan-600 hover:bg-cyan-500'} disabled:opacity-50 disabled:cursor-not-allowed text-white text-xs font-bold px-4 py-1.5 rounded flex items-center gap-2 transition-all`}
                    title={cachedBlob && exportMode === 'normal' ? "Instant Download available" : "High quality render"}
                 >
                    {renderStatus.state === 'idle' ? (
                        <>
                            {cachedBlob && exportMode === 'normal' ? <Zap size={14} fill="currentColor"/> : <Video size={14} />} 
                            {cachedBlob && exportMode === 'normal' ? 'INSTANT EXPORT' : 'EXPORT'}
                        </>
                    ) : (
                        <>
                            <Loader2 size={14} className="animate-spin" /> 
                            {renderStatus.state === 'analyzing' ? 'PROCESSING AUDIO' : 
                             renderStatus.state === 'encoding' ? 'ENCODING' :
                             `${Math.round((renderStatus.progress / (renderStatus.totalFrames || 1)) * 100)}%`}
                        </>
                    )}
                 </button>
             </div>
        </div>
      </header>

      {/* MAIN CONTENT GRID */}
      <div className="flex-1 flex overflow-hidden">

          <div className="w-96 bg-neutral-900 border-r border-white/5 flex flex-col shrink-0 z-10">
              <SettingsPanel 
                 config={rendererConfig} 
                 onUpdate={setRendererConfig}
                 data={data}
                 onUpdateData={setData}
                 currentTime={currentTime}
                 onSeek={handleSeek}
                 onJsonUpload={handleJsonUpload}
                 onSrtUpload={handleSrtUpload}
                 onAudioLayerAdd={handleAudioLayerAdd}
                 audioLayers={audioLayers}
                 onUpdateLayer={updateLayer}
                 onRemoveLayer={removeLayer}
                 onResetProject={handleResetProject}
              />
          </div>

          <div className="flex-1 bg-neutral-950 relative flex flex-col min-w-0">
               <div className={`flex-1 flex items-center justify-center p-8 overflow-hidden ${exportMode === 'alpha' ? 'bg-[conic-gradient(#333_90deg,transparent_90deg)] bg-[length:20px_20px] bg-neutral-800' : 'bg-[radial-gradient(circle_at_center,_#1a1a1a_1px,_transparent_1px)] bg-[length:20px_20px]'}`}>
                   <div 
                      className="relative shadow-2xl border border-white/10"
                      style={{
                          aspectRatio: `${aspectRatio}`,
                          height: aspectRatio > 1 ? 'auto' : '90%',
                          width: aspectRatio > 1 ? '90%' : 'auto',
                          maxHeight: '90%',
                          maxWidth: '90%'
                      }}
                   >
                       <CanvasVideoRenderer
                          ref={rendererRef}
                          data={data}
                          config={rendererConfig}
                          isPlaying={isPlaying}
                       />

                       {audioLayers.length === 0 && (
                           <div className="absolute inset-0 flex items-center justify-center bg-black/50 backdrop-blur-sm">
                               <div className="text-center">
                                   <p className="text-gray-400 font-mono text-sm mb-2">No Audio Layers</p>
                                   <p className="text-xs text-gray-600">Add an instrumental or vocal track in the Project tab</p>
                               </div>
                           </div>
                       )}
                   </div>
               </div>

               <div className="shrink-0 z-20">
                    <Controls
                        isPlaying={isPlaying}
                        onTogglePlay={togglePlay}
                        currentTime={currentTime}
                        duration={duration}
                        onSeek={handleSeek}
                        isRendering={renderStatus.state !== 'idle'}
                    />
               </div>
          </div>

      </div>
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { DEFAULT_LYRICS, TEMPLATES, RESOLUTIONS } from './constants';
import { CanvasVideoRenderer, CanvasVideoRendererRef } from './components/CanvasVideoRenderer';
import { Controls } from './components/Controls';
import { SettingsPanel } from './components/SettingsPanel';
import { LyricData, RenderStatus, AudioVisualizerData, Segment, Word, RendererConfig, ProjectFile, AudioLayer } from './types';
import { Save, FolderOpen, Activity, Loader2, Video, Download, RotateCcw, Check, Zap, Trash2, FileVideo } from 'lucide-react';

// @ts-ignore
import { Muxer as WebMMuxer, ArrayBufferTarget as WebMArrayBufferTarget } from 'webm-muxer';
// @ts-ignore
import { Muxer as Mp4Muxer, ArrayBufferTarget as Mp4ArrayBufferTarget } from 'mp4-muxer';

// Declarations for missing WebCodecs types to satisfy TypeScript
declare class AudioEncoder {
  constructor(init: { output: (chunk: any, meta: any) => void; error: (e: any) => void });
  configure(config: any): void;
  encode(data: any): void;
  flush(): Promise<void>;
  close(): void;
}

declare class AudioData {
  constructor(init: any);
  close(): void;
}

// Helper to parse SRT timestamp "00:00:12,345" or "00:00:12.345" to seconds
const parseSrtTimestamp = (timestamp: string): number => {
  if (!timestamp) return 0;
  // Normalize comma to dot and trim
  const normalized = timestamp.replace(',', '.').trim();
  const parts = normalized.split(':');

  if (parts.length < 3) return 0; 

  const hours = parseFloat(parts[0]);
  const minutes = parseFloat(parts[1]);
  const seconds = parseFloat(parts[2]);

  return (hours * 3600) + (minutes * 60) + seconds;
};

// Helper to parse SRT string to LyricData
const parseSrtToLyricData = (srtContent: string): LyricData => {
  const normalizedContent = srtContent.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  const blocks = normalizedContent.trim().split(/\n\s*\n/);

  const segments: Segment[] = [];

  blocks.forEach((block, index) => {
    const lines = block.split('\n');
    if (lines.length < 2) return;

    let timeLineIndex = lines.findIndex(l => l.includes('-->'));
    if (timeLineIndex === -1) return;

    const timeLine = lines[timeLineIndex];
    const [startStr, endStr] = timeLine.split('-->');

    if (!startStr || !endStr) return;

    const start = parseSrtTimestamp(startStr);
    const end = parseSrtTimestamp(endStr);

    // Extract text (lines after timestamp)
    // Remove HTML tags often found in SRTs
    const textLines = lines.slice(timeLineIndex + 1)
        .map(l => l.replace(/<[^>]*>/g, '').trim())
        .filter(l => l.length > 0);

    const fullText = textLines.join(' ');
    if (!fullText) return;

    // Create words with estimated timing
    const words: Word[] = [];
    const totalDuration = end - start;

    // Flatten words while keeping track of line numbers
    let allWords: {text: string, line: number}[] = [];
    textLines.forEach((line, lineIdx) => {
        const lineWords = line.split(/\s+/);
        lineWords.forEach(w => allWords.push({ text: w, line: lineIdx }));
    });

    const wordDuration = totalDuration / allWords.length;

    allWords.forEach((wObj, i) => {
      words.push({
        word: wObj.text,
        start: start + (i * wordDuration),
        end: start + ((i + 1) * wordDuration),
        probability: 1.0,
        line_number: wObj.line
      });
    });

    segments.push({
      id: index.toString(),
      start,
      end,
      text: fullText,
      section: 'verse',
      words
    });
  });

  return { segments };
};

export default function App() {
  const [data, setData] = useState<LyricData>(DEFAULT_LYRICS);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);

  // Multi-track State
  const [audioLayers, setAudioLayers] = useState<AudioLayer[]>([]);

  const [renderStatus, setRenderStatus] = useState<RenderStatus>({ state: 'idle', progress: 0 });
  const [audioVisualizerData, setAudioVisualizerData] = useState<AudioVisualizerData>({ bass: 0, mid: 0, high: 0, raw: new Uint8Array() });

  const [rendererConfig, setRendererConfig] = useState<RendererConfig>(TEMPLATES[0]);
  const [exportFormat, setExportFormat] = useState<'webm' | 'mp4'>('mp4');
  const [exportMode, setExportMode] = useState<'normal' | 'alpha'>('normal');

  // Caching / Instant Export State
  const [cachedBlob, setCachedBlob] = useState<Blob | null>(null);
  const [isCaching, setIsCaching] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);
  const audioDestinationRef = useRef<MediaStreamAudioDestinationNode | null>(null);

  // Web Audio Context Refs
  const audioContextRef = useRef<AudioContext | null>(null);
  const masterGainRef = useRef<GainNode | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const sourcesRef = useRef<Map<string, AudioBufferSourceNode>>(new Map());
  const gainsRef = useRef<Map<string, GainNode>>(new Map());

  const rendererRef = useRef<CanvasVideoRendererRef>(null);
  const requestRef = useRef<number>(0);
  const startTimeRef = useRef<number>(0);

  // Initialize Audio Engine
  const initAudioEngine = () => {
      if (!audioContextRef.current) {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          const ctx = new AudioContext();
          audioContextRef.current = ctx;

          // Master Gain
          const masterGain = ctx.createGain();
          masterGain.connect(ctx.destination);
          masterGainRef.current = masterGain;

          // Setup MediaStream Destination for Recording
          const dest = ctx.createMediaStreamDestination();
          masterGain.connect(dest);
          audioDestinationRef.current = dest;

          // Analyser
          const analyser = ctx.createAnalyser();
          analyser.fftSize = 256;
          masterGain.connect(analyser); // Master -> Analyser
          analyserRef.current = analyser;
      } else if (audioContextRef.current.state === 'suspended') {
          audioContextRef.current.resume();
      }
  };

  // Invalidate cache if PROJECT changes
  useEffect(() => {
    if (cachedBlob) {
        console.log("Project changed, invalidating cache...");
        setCachedBlob(null);
    }
  }, [data, rendererConfig, audioLayers]);

  // -- AUTOSAVE REMOVED --

  const handleResetProject = () => {
    if (confirm("Are you sure you want to reset the project to default values? All current changes will be lost.")) {
       setData(DEFAULT_LYRICS);
       setRendererConfig(TEMPLATES[0]);
       setAudioLayers([]);
       setCachedBlob(null);

       // Force stop any audio
       if (audioContextRef.current) {
           stopAllSources();
           audioContextRef.current.suspend();
           setIsPlaying(false);
           setCurrentTime(0);
       }
    }
  };

  // Handle Layer Upload
  const handleAudioLayerAdd = async (file: File) => {
      initAudioEngine();
      if (!audioContextRef.current) return;

      try {
          const arrayBuffer = await file.arrayBuffer();
          const audioBuffer = await audioContextRef.current.decodeAudioData(arrayBuffer);

          const newLayer: AudioLayer = {
              id: Date.now().toString() + Math.random().toString(),
              name: file.name,
              buffer: audioBuffer,
              volume: 1.0,
              muted: false,
              solo: false,
              duration: audioBuffer.duration
          };

          setAudioLayers(prev => {
              const updated = [...prev, newLayer];
              const maxDur = Math.max(...updated.map(l => l.duration));
              setDuration(maxDur);
              return updated;
          });
      } catch (e) {
          console.error("Error decoding audio", e);
          alert("Failed to load audio file.");
      }
  };

  const updateLayer = (id: string, updates: Partial<AudioLayer>) => {
      setAudioLayers(prev => prev.map(l => {
          if (l.id === id) return { ...l, ...updates };
          return l;
      }));
  };

  const removeLayer = (id: string) => {
      setAudioLayers(prev => {
          const updated = prev.filter(l => l.id !== id);
          const maxDur = Math.max(...updated.map(l => l.duration), 0);
          setDuration(maxDur);
          return updated;
      });
  };

  // Sync Audio Nodes with React State
  useEffect(() => {
     if (!audioContextRef.current) return;

     const hasSolo = audioLayers.some(l => l.solo);

     audioLayers.forEach(layer => {
         if (!gainsRef.current.has(layer.id)) {
             const g = audioContextRef.current!.createGain();
             if (masterGainRef.current) g.connect(masterGainRef.current);
             gainsRef.current.set(layer.id, g);
         }

         const gainNode = gainsRef.current.get(layer.id);
         if (gainNode) {
             const effectiveMute = layer.muted || (hasSolo && !layer.solo);
             const currentTime = audioContextRef.current!.currentTime;
             gainNode.gain.cancelScheduledValues(currentTime);
             gainNode.gain.setTargetAtTime(effectiveMute ? 0 : layer.volume, currentTime, 0.05);
         }
     });

     gainsRef.current.forEach((val, key) => {
         if (!audioLayers.find(l => l.id === key)) {
             val.disconnect();
             gainsRef.current.delete(key);
         }
     });

  }, [audioLayers]);


  const stopAllSources = () => {
      sourcesRef.current.forEach(source => {
          try { source.stop(); } catch(e) {}
          source.disconnect();
      });
      sourcesRef.current.clear();
  };

  const startAllSources = (offset: number) => {
      if (!audioContextRef.current) return;
      stopAllSources();

      audioLayers.forEach(layer => {
          const source = audioContextRef.current!.createBufferSource();
          source.buffer = layer.buffer;

          const gainNode = gainsRef.current.get(layer.id);
          if (gainNode) {
              source.connect(gainNode);
          }

          source.start(0, offset);
          sourcesRef.current.set(layer.id, source);
      });
  };

  // --- SMART CACHING LOGIC ---
  const startRecordingCache = () => {
      if (!rendererRef.current?.canvas || !audioDestinationRef.current) return;

      try {
          // 1. Capture Canvas Stream (60fps preferred for smoothness)
          const canvasStream = rendererRef.current.canvas.captureStream(60);

          // 2. Capture Audio Stream
          const audioStream = audioDestinationRef.current.stream;

          // 3. Combine tracks
          const combinedTracks = [
              ...canvasStream.getVideoTracks(),
              ...audioStream.getAudioTracks()
          ];
          const combinedStream = new MediaStream(combinedTracks);

          // 4. Initialize Recorder
          // Prefer higher bitrate for "Cached" quality
          const options: MediaRecorderOptions = {
              mimeType: MediaRecorder.isTypeSupported('video/webm;codecs=vp9') ? 'video/webm;codecs=vp9' : 'video/webm',
              videoBitsPerSecond: 8000000 // 8 Mbps
          };

          const recorder = new MediaRecorder(combinedStream, options);
          recordedChunksRef.current = [];

          recorder.ondataavailable = (e) => {
              if (e.data.size > 0) {
                  recordedChunksRef.current.push(e.data);
              }
          };

          recorder.onstop = () => {
              // Only save if we stopped intentionally (end of song) not interrupted
              // Logic is handled in loop or handleSeek
          };

          recorder.start();
          mediaRecorderRef.current = recorder;
          setIsCaching(true);
          console.log("Started caching playback...");
      } catch (err) {
          console.error("Failed to start caching", err);
      }
  };

  const stopRecordingCache = (save: boolean) => {
      if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
          mediaRecorderRef.current.stop();

          if (save && recordedChunksRef.current.length > 0) {
               const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' });
               setCachedBlob(blob);
               console.log("Caching complete. Blob created size:", blob.size);
          } else {
              console.log("Caching discarded.");
          }
      }
      setIsCaching(false);
      mediaRecorderRef.current = null;
  };

  const togglePlay = () => {
    initAudioEngine();
    if (!audioContextRef.current) return;

    if (isPlaying) {
      // Pause
      // If we were caching, this invalidates the "perfect run", so discard.
      if (isCaching) stopRecordingCache(false);

      audioContextRef.current.suspend();
      setIsPlaying(false);
    } else {
      // Play
      audioContextRef.current.resume();

      // If sources aren't running
      if (sourcesRef.current.size === 0) {
          // If starting from the very beginning, try to cache this run
          if (currentTime < 0.1) {
              // Clear old cache
              setCachedBlob(null); 
              startRecordingCache();
          }

          startAllSources(currentTime);
          startTimeRef.current = audioContextRef.current.currentTime - currentTime;
      }
      setIsPlaying(true);
    }
  };

  const handleSeek = (time: number) => {
      if (!audioContextRef.current) return;

      // Seeking invalidates current recording run
      if (isCaching) stopRecordingCache(false);

      const wasPlaying = isPlaying;
      audioContextRef.current.suspend();
      stopAllSources();

      setCurrentTime(time);
      startTimeRef.current = audioContextRef.current.currentTime - time;

      if (wasPlaying) {
          startAllSources(time);
          audioContextRef.current.resume();
      }
  };

  const analyzeAudio = () => {
    if (analyserRef.current) {
      const bufferLength = analyserRef.current.frequencyBinCount;
      const dataArray = new Uint8Array(bufferLength);
      analyserRef.current.getByteFrequencyData(dataArray);

      const bassRange = dataArray.slice(0, 10);
      const midRange = dataArray.slice(10, 100);
      const highRange = dataArray.slice(100, 200);

      const avg = (arr: Uint8Array) => arr.reduce((a, b) => a + b, 0) / arr.length;

      setAudioVisualizerData({
        bass: avg(bassRange) / 255,
        mid: avg(midRange) / 255,
        high: avg(highRange) / 255,
        raw: dataArray
      });
    }
  };

  const loop = () => {
    if (isPlaying && audioContextRef.current) {
        const now = audioContextRef.current.currentTime;
        let syncedTime = now - startTimeRef.current;

        if (syncedTime >= duration && duration > 0) {
            syncedTime = duration;

            // If we reached the end AND we were caching, save it!
            if (isCaching) {
                stopRecordingCache(true);
            }

            setIsPlaying(false);
            stopAllSources();
            audioContextRef.current.suspend();
        }

        setCurrentTime(syncedTime);
        analyzeAudio();
    }

    if (rendererRef.current) {
        // Playback render mode is always normal (not alpha)
        rendererRef.current.drawFrame(currentTime, audioVisualizerData, false);
    }

    requestRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current);
  }, [currentTime, audioVisualizerData, isPlaying, duration, isCaching]);


  const handleJsonUpload = (jsonStr: string) => {
    try {
      const parsed = JSON.parse(jsonStr);
      if (parsed.segments) setData(parsed);
    } catch (e) {
      alert("Error parsing JSON");
    }
  };

  const handleSrtUpload = (srtStr: string) => {
    try {
        const parsed = parseSrtToLyricData(srtStr);
        if (parsed.segments.length > 0) setData(parsed);
    } catch (e) {
        alert("Error parsing SRT");
    }
  };

  const handleSaveProject = () => {
      const project: ProjectFile = {
          version: '1.0',
          timestamp: Date.now(),
          name: audioLayers.length > 0 ? audioLayers[0].name : 'Untitled Project',
          lyricData: data,
          config: rendererConfig
      };

      const blob = new Blob([JSON.stringify(project, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `kinetic-project-${Date.now()}.json`;
      a.click();
      URL.revokeObjectURL(url);
  };

  const handleLoadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (ev) => {
          try {
              if (ev.target?.result) {
                  const project = JSON.parse(ev.target.result as string) as ProjectFile;
                  if (project.lyricData && project.config) {
                      setData(project.lyricData);
                      setRendererConfig(project.config);
                      setCachedBlob(null); // Clear cache on load
                      alert("Project loaded! Please re-add your audio layers.");
                  }
              }
          } catch(err) {
              alert("Failed to parse project file.");
          }
      };
      reader.readAsText(file);
  };

  const downloadCachedVideo = () => {
      if (!cachedBlob) return;
      const url = URL.createObjectURL(cachedBlob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `kinetic-lyric-video-quick.${cachedBlob.type.includes('mp4') ? 'mp4' : 'webm'}`;
      a.click();
      URL.revokeObjectURL(url);
  };

  // --- HIGH STABILITY RENDERING ENGINE ---
  const startRendering = async () => {
    if (audioLayers.length === 0) {
      alert("Please add at least one audio layer.");
      return;
    }

    // Check if we can just use cache (ONLY for Normal export)
    if (cachedBlob && exportMode === 'normal') {
        if (confirm("A cached version from your playback is available! \n\nDo you want to download it instantly (Instant) or render a high-quality version frame-by-frame (Slow)?\n\nClick OK for Instant, Cancel for Slow Render.")) {
            downloadCachedVideo();
            return;
        }
    }

    if (renderStatus.state !== 'idle') return;

    const resConfig = RESOLUTIONS.find(r => r.id === rendererConfig.resolutionId) || RESOLUTIONS[0];
    const VIDEO_WIDTH = resConfig.width;
    const VIDEO_HEIGHT = resConfig.height;

    setRenderStatus({ state: 'analyzing', progress: 0 });

    // Stop live playback to free resources
    if (isPlaying && audioContextRef.current) {
        audioContextRef.current.suspend();
        setIsPlaying(false);
    }

    try {
      const sampleRate = 44100;
      const FPS = 30;
      const totalFrames = Math.ceil(duration * FPS);

      // PHASE 1: AUDIO RENDER & ANALYSIS (Fast, Offline)
      console.log("Phase 1: Rendering Audio & Extracting Analysis...");

      const offlineCtx = new OfflineAudioContext(2, Math.ceil(duration * sampleRate), sampleRate);
      const offlineMasterGain = offlineCtx.createGain();
      offlineMasterGain.connect(offlineCtx.destination);

      const offlineAnalyser = offlineCtx.createAnalyser();
      offlineAnalyser.fftSize = 256;
      offlineMasterGain.connect(offlineAnalyser);

      const hasSolo = audioLayers.some(l => l.solo);

      // Set up Audio Graph in Offline Context
      audioLayers.forEach(layer => {
           const effectiveMute = layer.muted || (hasSolo && !layer.solo);
           if (effectiveMute) return;

           const source = offlineCtx.createBufferSource();
           source.buffer = layer.buffer;

           const gain = offlineCtx.createGain();
           gain.gain.value = layer.volume;

           source.connect(gain);
           gain.connect(offlineMasterGain);
           source.start(0);
      });

      // Prepare Array to hold FFT data for every frame
      const analysisFrames: AudioVisualizerData[] = new Array(totalFrames);
      const dataArray = new Uint8Array(offlineAnalyser.frequencyBinCount);
      const frameDuration = 1 / FPS;

      // Schedule Suspend for every frame to grab FFT data
      for (let i = 0; i < totalFrames; i++) {
           const t = i * frameDuration;

           // Safety: Do not schedule suspend past duration
           if (t >= duration) break;

           offlineCtx.suspend(t).then(async () => {
               offlineAnalyser.getByteFrequencyData(dataArray);
               const bass = dataArray.slice(0, 10).reduce((a,b)=>a+b,0) / 10 / 255;
               const mid = dataArray.slice(10, 100).reduce((a,b)=>a+b,0) / 90 / 255;
               const high = dataArray.slice(100, 200).reduce((a,b)=>a+b,0) / 100 / 255;

               analysisFrames[i] = {
                   bass, mid, high,
                   raw: new Uint8Array(dataArray) // Copy buffer
               };
               // IMPORTANT: Must resume to continue to next suspend point
               await offlineCtx.resume();
           }).catch((e) => console.error("Suspend error", e));
      }

      // Execute Audio Rendering
      const renderedAudioBuffer = await offlineCtx.startRendering();
      console.log("Phase 1 Complete. Audio rendered.");

      // PHASE 2: VIDEO ENCODING (Batched, Backpressure Managed)
      setRenderStatus({ state: 'rendering', progress: 0, totalFrames });

      // FORCE WEBM FOR ALPHA EXPORT
      const finalExportFormat = exportMode === 'alpha' ? 'webm' : exportFormat;

      let muxer: any;
      if (finalExportFormat === 'mp4') {
        muxer = new Mp4Muxer({
            target: new Mp4ArrayBufferTarget(),
            video: { codec: 'avc', width: VIDEO_WIDTH, height: VIDEO_HEIGHT },
            audio: { codec: 'aac', numberOfChannels: 2, sampleRate: sampleRate },
            fastStart: false 
        });
      } else {
        // WEBM
        muxer = new WebMMuxer({
            target: new WebMArrayBufferTarget(),
            video: { 
                codec: 'V_VP9', 
                width: VIDEO_WIDTH, 
                height: VIDEO_HEIGHT, 
                frameRate: FPS,
                alpha: exportMode === 'alpha' // ENABLE ALPHA IN MUXER
            },
            audio: { codec: 'A_OPUS', numberOfChannels: 2, sampleRate: sampleRate }
        });
      }

      // Track encoder errors to stop the loop
      let encoderError: Error | null = null;

      const videoEncoder = new VideoEncoder({
        output: (chunk, meta) => muxer.addVideoChunk(chunk, meta),
        error: (e) => {
            encoderError = e;
            console.error("VideoEncoder error:", e);
        }
      });

      const codecConfig: VideoEncoderConfig = finalExportFormat === 'mp4' 
      ? { codec: 'avc1.4d002a', width: VIDEO_WIDTH, height: VIDEO_HEIGHT, bitrate: 8_000_000 } // Higher bitrate
      : { 
          codec: 'vp09.00.10.08', 
          width: VIDEO_WIDTH, 
          height: VIDEO_HEIGHT, 
          bitrate: 6_000_000,
          bitrateMode: exportMode === 'alpha' ? 'variable' : undefined, // Variable can help with alpha in some profiles
          alpha: exportMode === 'alpha' ? 'keep' : 'discard' // ENABLE ALPHA IN ENCODER
        };

      try {
          videoEncoder.configure(codecConfig);
      } catch (e) {
          console.error("Encoder Configuration Failed:", e);
          alert("Your browser does not support the selected export format (likely Alpha transparency). Please switch to 'Normal' mode.");
          setRenderStatus({ state: 'idle', progress: 0 });
          return;
      }

      const canvas = rendererRef.current?.canvas;
      if (!canvas) throw new Error("Canvas not found");

      // BATCH RENDERING LOOP
      const BATCH_SIZE = 10; // Process frames in small batches to keep UI alive

      for (let i = 0; i < totalFrames; i++) {
         if (encoderError) {
             throw new Error(`Encoding failed: ${encoderError.message || 'Unknown error'}`);
         }

         const time = i * frameDuration;
         const analysis = analysisFrames[i] || { bass: 0, mid: 0, high: 0, raw: new Uint8Array() };

         // WAIT FOR VIDEO SEEK (Fixes background video flickering)
         if (rendererRef.current?.seekToTime) {
             await rendererRef.current.seekToTime(time);
         }

         // Draw Frame with Alpha Support
         rendererRef.current?.drawFrame(time, analysis, exportMode === 'alpha');

         // Create VideoFrame from Canvas
         // If alpha, ensure context was created with alpha: true (it is in CanvasVideoRenderer)
         const frame = new VideoFrame(canvas, { 
             timestamp: time * 1_000_000,
             alpha: exportMode === 'alpha' ? 'keep' : 'discard' 
         });

         const keyFrame = i % (FPS * 2) === 0; // Keyframe every 2 seconds

         // Backpressure: If queue is full, wait for it to drain
         if (videoEncoder.encodeQueueSize > 5) {
             await videoEncoder.flush();
         }

         try {
             videoEncoder.encode(frame, { keyFrame });
         } catch (e) {
             frame.close();
             // Check if it's because of a previous error
             if (encoderError) throw new Error("Encoder closed unexpectedly.");
             throw e;
         }

         frame.close(); // Important: Release GPU memory immediately

         // Update UI & Yield to Event Loop every batch
         if (i % BATCH_SIZE === 0) {
             setRenderStatus(prev => ({ ...prev, progress: i }));
             await new Promise(resolve => setTimeout(resolve, 0)); // Yield to main thread
         }
      }

      setRenderStatus(prev => ({ ...prev, progress: totalFrames }));

      // PHASE 3: FINALIZE
      setRenderStatus({ state: 'encoding', progress: 100, totalFrames });
      await videoEncoder.flush();
      videoEncoder.close();

      // Audio Encoding (Skip for Alpha? No, usually keep audio)
      const audioEncoder = new AudioEncoder({
        output: (chunk, meta) => muxer.addAudioChunk(chunk, meta),
        error: (e) => console.error("AudioEncoder error:", e)
      });

      const audioCodecString = finalExportFormat === 'mp4' ? 'mp4a.40.2' : 'opus';
      audioEncoder.configure({
        codec: audioCodecString,
        numberOfChannels: 2,
        sampleRate: sampleRate,
        bitrate: 192000
      });

      // Interleave Audio Data
      const numberOfFrames = renderedAudioBuffer.length;
      const numberOfChannels = renderedAudioBuffer.numberOfChannels;
      const interleaved = new Float32Array(numberOfFrames * numberOfChannels);

      // Safe channel getters
      const channel0 = renderedAudioBuffer.getChannelData(0);
      const channel1 = numberOfChannels > 1 ? renderedAudioBuffer.getChannelData(1) : channel0;

      for(let i=0; i<numberOfFrames; i++) {
          interleaved[i*2] = channel0[i];
          interleaved[i*2+1] = channel1[i];
      }

      const audioData = new AudioData({
        format: 'f32',
        sampleRate: sampleRate,
        numberOfFrames: numberOfFrames,
        numberOfChannels: numberOfChannels,
        timestamp: 0,
        data: interleaved
      });

      audioEncoder.encode(audioData);
      await audioEncoder.flush();
      audioEncoder.close();

      // Finalize Muxer
      muxer.finalize();
      const { buffer } = muxer.target;
      const blob = new Blob([buffer], { type: finalExportFormat === 'mp4' ? 'video/mp4' : 'video/webm' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `kinetic-lyric-video${exportMode === 'alpha' ? '-alpha' : ''}.${finalExportFormat}`;
      a.click();

      setRenderStatus({ state: 'done', progress: 100 });
      setTimeout(() => setRenderStatus({ state: 'idle', progress: 0 }), 3000);

    } catch (e) {
      console.error("Export failed", e);
      // More friendly error for alpha issue
      if (exportMode === 'alpha' && (e as any)?.message?.includes('Alpha')) {
          alert("Export Failed: Your browser doesn't support transparent video encoding. Please switch 'ALPHA' to 'NORMAL' and try again.");
      } else {
          alert(`Rendering failed: ${(e as any)?.message || 'Unknown error'}`);
      }
      setRenderStatus({ state: 'idle', progress: 0 });
    }
  };

  const viewportResolution = RESOLUTIONS.find(r => r.id === rendererConfig.resolutionId) || RESOLUTIONS[0];
  const aspectRatio = viewportResolution.width / viewportResolution.height;

  return (
    <div className="h-screen w-screen flex flex-col bg-neutral-950 text-white overflow-hidden font-sans">

      {/* HEADER */}
      <header className="h-14 border-b border-white/10 flex items-center justify-between px-4 bg-neutral-900 shrink-0 z-20">
        <div className="flex items-center gap-2">
           <Activity className="text-cyan-400" />
           <h1 className="font-black tracking-tighter text-lg">KINETIC<span className="text-cyan-400">FLOW</span></h1>
        </div>

        {/* Center: Status Indicators */}
        <div className="flex items-center gap-4">
             {isCaching && (
                 <div className="flex items-center gap-1.5 bg-red-950/50 border border-red-500/30 px-2 py-0.5 rounded-full animate-pulse">
                     <div className="w-2 h-2 rounded-full bg-red-500" />
                     <span className="text-[10px] text-red-200 font-bold uppercase tracking-wide">Caching for Export</span>
                 </div>
             )}

             {cachedBlob && !isCaching && (
                 <div className="flex items-center gap-1.5 bg-green-950/50 border border-green-500/30 px-2 py-0.5 rounded-full">
                     <Zap size={10} className="text-green-400 fill-current" />
                     <span className="text-[10px] text-green-200 font-bold uppercase tracking-wide">Instant Export Ready</span>
                 </div>
             )}
        </div>

        <div className="flex items-center gap-2">
             <div className="flex items-center bg-neutral-800 rounded-md border border-white/5 mr-4">
                  <button 
                    onClick={handleResetProject}
                    title="Reset Project"
                    className="p-2 hover:bg-neutral-700 text-gray-400 hover:text-red-400 transition-colors border-r border-white/5"
                  >
                      <RotateCcw size={18} />
                  </button>
                  <button 
                    onClick={handleSaveProject}
                    title="Save Project"
                    className="p-2 hover:bg-neutral-700 text-gray-400 hover:text-cyan-400 transition-colors border-r border-white/5"
                  >
                      <Save size={18} />
                  </button>
                  <label 
                    title="Load Project"
                    className="p-2 hover:bg-neutral-700 text-gray-400 hover:text-cyan-400 transition-colors cursor-pointer"
                  >
                      <FolderOpen size={18} />
                      <input type="file" accept=".json" onChange={handleLoadProject} className="hidden"/>
                  </label>
             </div>

             <div className="flex items-center gap-2 bg-neutral-800 p-1 rounded-md border border-white/5">
                 <div className="flex items-center px-1 border-r border-white/5 mr-1">
                     <button
                        onClick={() => setExportMode('normal')}
                        className={`text-[10px] px-2 py-1 font-bold rounded ${exportMode === 'normal' ? 'bg-neutral-600 text-white' : 'text-gray-400 hover:text-white'}`}
                     >
                        NORMAL
                     </button>
                     <button
                        onClick={() => setExportMode('alpha')}
                        className={`text-[10px] px-2 py-1 font-bold rounded flex items-center gap-1 ${exportMode === 'alpha' ? 'bg-neutral-600 text-white' : 'text-gray-400 hover:text-white'}`}
                        title="Transparent Background (WEBM)"
                     >
                        ALPHA
                     </button>
                 </div>

                 {!cachedBlob && exportMode === 'normal' && (
                    <select 
                        value={exportFormat}
                        onChange={(e) => setExportFormat(e.target.value as any)}
                        className="bg-transparent text-xs font-bold text-gray-300 outline-none px-2 py-1"
                        disabled={renderStatus.state !== 'idle'}
                        >
                        <option value="mp4">MP4</option>
                        <option value="webm">WEBM</option>
                    </select>
                 )}
                 <button
                    onClick={startRendering}
                    disabled={renderStatus.state !== 'idle' || audioLayers.length === 0}
                    className={`${cachedBlob && exportMode === 'normal' ? 'bg-green-600 hover:bg-green-500' : 'bg-cyan-600 hover:bg-cyan-500'} disabled:opacity-50 disabled:cursor-not-allowed text-white text-xs font-bold px-4 py-1.5 rounded flex items-center gap-2 transition-all`}
                    title={cachedBlob && exportMode === 'normal' ? "Instant Download available" : "High quality render"}
                 >
                    {renderStatus.state === 'idle' ? (
                        <>
                            {cachedBlob && exportMode === 'normal' ? <Zap size={14} fill="currentColor"/> : <Video size={14} />} 
                            {cachedBlob && exportMode === 'normal' ? 'INSTANT EXPORT' : 'EXPORT'}
                        </>
                    ) : (
                        <>
                            <Loader2 size={14} className="animate-spin" /> 
                            {renderStatus.state === 'analyzing' ? 'PROCESSING AUDIO' : 
                             renderStatus.state === 'encoding' ? 'ENCODING' :
                             `${Math.round((renderStatus.progress / (renderStatus.totalFrames || 1)) * 100)}%`}
                        </>
                    )}
                 </button>
             </div>
        </div>
      </header>

      {/* MAIN CONTENT GRID */}
      <div className="flex-1 flex overflow-hidden">

          <div className="w-96 bg-neutral-900 border-r border-white/5 flex flex-col shrink-0 z-10">
              <SettingsPanel 
                 config={rendererConfig} 
                 onUpdate={setRendererConfig}
                 data={data}
                 onUpdateData={setData}
                 currentTime={currentTime}
                 onSeek={handleSeek}
                 onJsonUpload={handleJsonUpload}
                 onSrtUpload={handleSrtUpload}
                 onAudioLayerAdd={handleAudioLayerAdd}
                 audioLayers={audioLayers}
                 onUpdateLayer={updateLayer}
                 onRemoveLayer={removeLayer}
                 onResetProject={handleResetProject}
              />
          </div>

          <div className="flex-1 bg-neutral-950 relative flex flex-col min-w-0">
               <div className={`flex-1 flex items-center justify-center p-8 overflow-hidden ${exportMode === 'alpha' ? 'bg-[conic-gradient(#333_90deg,transparent_90deg)] bg-[length:20px_20px] bg-neutral-800' : 'bg-[radial-gradient(circle_at_center,_#1a1a1a_1px,_transparent_1px)] bg-[length:20px_20px]'}`}>
                   <div 
                      className="relative shadow-2xl border border-white/10"
                      style={{
                          aspectRatio: `${aspectRatio}`,
                          height: aspectRatio > 1 ? 'auto' : '90%',
                          width: aspectRatio > 1 ? '90%' : 'auto',
                          maxHeight: '90%',
                          maxWidth: '90%'
                      }}
                   >
                       <CanvasVideoRenderer
                          ref={rendererRef}
                          data={data}
                          config={rendererConfig}
                          isPlaying={isPlaying}
                       />

                       {audioLayers.length === 0 && (
                           <div className="absolute inset-0 flex items-center justify-center bg-black/50 backdrop-blur-sm">
                               <div className="text-center">
                                   <p className="text-gray-400 font-mono text-sm mb-2">No Audio Layers</p>
                                   <p className="text-xs text-gray-600">Add an instrumental or vocal track in the Project tab</p>
                               </div>
                           </div>
                       )}
                   </div>
               </div>

               <div className="shrink-0 z-20">
                    <Controls
                        isPlaying={isPlaying}
                        onTogglePlay={togglePlay}
                        currentTime={currentTime}
                        duration={duration}
                        onSeek={handleSeek}
                        isRendering={renderStatus.state !== 'idle'}
                    />
               </div>
          </div>

      </div>
    </div>
  );
}

import React, { useState, useRef } from 'react';
import { Sliders, LayoutTemplate, Palette, Sparkles, Video, Type, Image as ImageIcon, Upload, Grid, Music, Camera, Aperture, Clock, Plus, Trash2, Monitor, Timer, FolderOpen, FileJson, FileText, FileAudio, Volume2, VolumeX, Mic2, Layers, AlignLeft, Tags, RotateCcw } from 'lucide-react';
import { TEMPLATES, FONTS, RESOLUTIONS } from '../constants';
import { RendererConfig, AnimationKeyframe, AudioLayer, LyricData, SectionType, SectionStyle, ImageEffect } from '../types';
import { TimelineEditor } from './TimelineEditor';

interface SettingsPanelProps {
  config: RendererConfig;
  onUpdate: (config: RendererConfig) => void;
  // Lyrics Data
  data: LyricData;
  onUpdateData: (data: LyricData) => void;
  // Playback
  currentTime: number;
  onSeek: (time: number) => void;
  // File Handlers
  onJsonUpload: (jsonStr: string) => void;
  onSrtUpload: (srtStr: string) => void;
  onAudioLayerAdd: (file: File) => void;
  // Audio Mixer Handlers
  audioLayers: AudioLayer[];
  onUpdateLayer: (id: string, updates: Partial<AudioLayer>) => void;
  onRemoveLayer: (id: string) => void;
  // Project Management
  onResetProject: () => void;
}

// Helper Components
const ToggleInput = ({ label, value, onChange }: { label: string, value: boolean, onChange: (v: boolean) => void }) => (
  <div className="flex items-center justify-between">
    <span className="text-sm font-medium text-gray-400">{label}</span>
    <button
      onClick={() => onChange(!value)}
      className={`w-10 h-5 rounded-full relative transition-colors ${value ? 'bg-cyan-600' : 'bg-neutral-700'}`}
    >
      <div className={`absolute top-1 left-1 w-3 h-3 bg-white rounded-full transition-transform ${value ? 'translate-x-5' : 'translate-x-0'}`} />
    </button>
  </div>
);

const MultiToggleInput = ({ label, values, options, onChange }: { label: string, values: string[], options: string[], onChange: (v: string[]) => void }) => (
    <div className="flex flex-col gap-2">
      <label className="text-xs font-bold text-gray-500 uppercase">{label}</label>
      <div className="flex flex-wrap gap-2">
        {options.map(opt => {
            const isActive = values.includes(opt);
            return (
                <button
                    key={opt}
                    onClick={() => {
                        if (isActive) {
                            onChange(values.filter(v => v !== opt));
                        } else {
                            onChange([...values, opt]);
                        }
                    }}
                    className={`px-3 py-1.5 rounded text-[10px] font-bold uppercase transition-all border ${
                        isActive 
                        ? 'bg-cyan-600 text-white border-cyan-500' 
                        : 'bg-neutral-800 text-gray-400 border-white/5 hover:border-white/20'
                    }`}
                >
                    {opt}
                </button>
            );
        })}
      </div>
    </div>
);

const SelectInput = ({ label, value, options, onChange }: { label: string, value: string, options: string[], onChange: (v: any) => void }) => (
  <div className="flex flex-col gap-1">
    <label className="text-xs font-bold text-gray-500 uppercase">{label}</label>
    <select
      value={value}
      onChange={(e) => onChange(e.target.value)}
      className="bg-neutral-900 border border-white/10 rounded-md px-2 py-1.5 text-sm text-gray-200 focus:border-cyan-500 outline-none"
    >
      {options.map(opt => (
        <option key={opt} value={opt}>{opt.charAt(0).toUpperCase() + opt.slice(1)}</option>
      ))}
    </select>
  </div>
);

const ColorInput = ({ label, value, onChange }: { label: string, value: string, onChange: (v: string) => void }) => (
  <div className="flex items-center justify-between bg-neutral-900 p-2 rounded-md border border-white/5">
    <span className="text-xs font-bold text-gray-400">{label}</span>
    <div className="flex items-center gap-2">
      <div className="w-4 h-4 rounded-full border border-white/20" style={{ background: value }}></div>
      <input
        type="color"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="opacity-0 absolute w-8 h-8 cursor-pointer"
      />
      <span className="text-xs font-mono text-gray-500">{value}</span>
    </div>
  </div>
);

interface KeyframeEditorProps {
    keyframe: AnimationKeyframe;
    defaults: RendererConfig;
    onUpdate: (id: string, updates: Partial<AnimationKeyframe> | Partial<AnimationKeyframe['values']>) => void;
    onDelete: (id: string) => void;
}

const KeyframeEditor: React.FC<KeyframeEditorProps> = ({ keyframe, defaults, onUpdate, onDelete }) => {
    return (
        <div className="bg-neutral-900 p-4 rounded-xl border border-white/10 space-y-4 shadow-lg">
            <div className="flex items-center justify-between border-b border-white/5 pb-2">
                 <h4 className="font-bold text-sm text-cyan-400 flex items-center gap-2">
                    <Sliders size={14} /> Edit Keyframe
                 </h4>
                 <button 
                    onClick={() => onDelete(keyframe.id)}
                    className="text-red-400 hover:text-red-300 p-1 hover:bg-red-900/20 rounded transition-colors"
                    title="Delete Keyframe"
                 >
                    <Trash2 size={16} />
                 </button>
            </div>

            <div className="flex flex-col gap-1">
                 <label className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1">
                    <Timer size={12} /> Timestamp (seconds)
                 </label>
                 <input 
                    type="number" 
                    step="0.1"
                    min="0"
                    value={keyframe.time.toFixed(2)}
                    onChange={(e) => onUpdate(keyframe.id, { time: parseFloat(e.target.value) })}
                    className="bg-black border border-white/10 rounded-md px-2 py-1.5 text-sm text-white focus:border-cyan-500 outline-none font-mono"
                 />
            </div>

            <div className="space-y-3 pt-2 border-t border-white/5">
                <ColorInput 
                    label="Active Color" 
                    value={keyframe.values.colors_active || defaults.colors.active} 
                    onChange={(v) => onUpdate(keyframe.id, { values: { ...keyframe.values, colors_active: v } })} 
                />
                <ColorInput 
                    label="Background Color" 
                    value={keyframe.values.background_color || defaults.background.color} 
                    onChange={(v) => onUpdate(keyframe.id, { values: { ...keyframe.values, background_color: v } })} 
                />

                {/* Image Effect Override in Keyframe */}
                <MultiToggleInput 
                    label="Active Image Effects" 
                    values={keyframe.values.image_effects || defaults.background.imageEffects || []} 
                    options={['dark-error', 'red-error', 'zoom-slow', 'chromatic-shift', 'alert', 'thermal', 'vhs-stripes']} 
                    onChange={(v) => onUpdate(keyframe.id, { values: { ...keyframe.values, image_effects: v as ImageEffect[] } })} 
                />

                <div>
                    <div className="flex justify-between text-xs text-gray-400 mb-1">
                        <span>Effect Speed</span>
                        <span>{(keyframe.values.image_effect_speed ?? defaults.background.imageEffectSpeed ?? 1.0).toFixed(1)}x</span>
                    </div>
                    <input 
                        type="range" min="0.1" max="5.0" step="0.1" 
                        value={keyframe.values.image_effect_speed ?? defaults.background.imageEffectSpeed ?? 1.0} 
                        onChange={(e) => onUpdate(keyframe.id, { values: { ...keyframe.values, image_effect_speed: parseFloat(e.target.value) } })}
                        className="w-full h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                    />
                </div>

                <div>
                    <div className="flex justify-between text-xs text-gray-400 mb-1">
                        <span>Glow Intensity</span>
                        <span>{Math.round((keyframe.values.effects_glow ?? defaults.effects.glow) * 100)}%</span>
                    </div>
                    <input 
                        type="range" min="0" max="1" step="0.1" 
                        value={keyframe.values.effects_glow ?? defaults.effects.glow} 
                        onChange={(e) => onUpdate(keyframe.id, { values: { ...keyframe.values, effects_glow: parseFloat(e.target.value) } })}
                        className="w-full h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                    />
                </div>

                <div>
                    <div className="flex justify-between text-xs text-gray-400 mb-1">
                        <span>Camera Zoom (Offset)</span>
                        <span>{keyframe.values.camera_zoom?.toFixed(2) || 0}</span>
                    </div>
                    <input 
                        type="range" min="-0.5" max="2.0" step="0.1" 
                        value={keyframe.values.camera_zoom || 0} 
                        onChange={(e) => onUpdate(keyframe.id, { values: { ...keyframe.values, camera_zoom: parseFloat(e.target.value) } })}
                        className="w-full h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                    />
                </div>

                <div>
                    <div className="flex justify-between text-xs text-gray-400 mb-1">
                        <span>Camera Rotate (Rad)</span>
                        <span>{keyframe.values.camera_rotate?.toFixed(2) || 0}</span>
                    </div>
                    <input 
                        type="range" min="-3.14" max="3.14" step="0.1" 
                        value={keyframe.values.camera_rotate || 0} 
                        onChange={(e) => onUpdate(keyframe.id, { values: { ...keyframe.values, camera_rotate: parseFloat(e.target.value) } })}
                        className="w-full h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                    />
                </div>
            </div>
        </div>
    );
};

export const SettingsPanel: React.FC<SettingsPanelProps> = ({ 
    config, 
    onUpdate, 
    data,
    onUpdateData,
    currentTime,
    onSeek,
    onAudioLayerAdd,
    audioLayers,
    onUpdateLayer,
    onRemoveLayer,
    onJsonUpload,
    onSrtUpload,
    onResetProject
}) => {
  const [activeTab, setActiveTab] = useState<'project' | 'lyrics' | 'sections' | 'templates' | 'customize' | 'timeline'>('project');
  const [selectedKeyframeId, setSelectedKeyframeId] = useState<string | null>(null);
  const bgInputRef = useRef<HTMLInputElement>(null);
  const fontInputRef = useRef<HTMLInputElement>(null);

  // Refs for Project Files
  const jsonInputRef = useRef<HTMLInputElement>(null);
  const srtInputRef = useRef<HTMLInputElement>(null);
  const audioInputRef = useRef<HTMLInputElement>(null);

  const handleTemplateSelect = (template: RendererConfig) => {
    onUpdate(JSON.parse(JSON.stringify(template)));
  };

  const updateNested = (section: keyof RendererConfig, key: string, value: any) => {
    const newConfig = JSON.parse(JSON.stringify(config));
    // @ts-ignore
    newConfig[section][key] = value;
    onUpdate(newConfig);
  };

  const updateSectionStyle = (section: SectionType, key: keyof SectionStyle, value: any) => {
      const newConfig = JSON.parse(JSON.stringify(config));
      if (!newConfig.sectionStyles) newConfig.sectionStyles = {};
      if (!newConfig.sectionStyles[section]) newConfig.sectionStyles[section] = { enabled: false };

      // @ts-ignore
      newConfig.sectionStyles[section][key] = value;
      onUpdate(newConfig);
  };

  const updateColor = (key: keyof RendererConfig['colors'], value: string) => {
    updateNested('colors', key, value);
  };

  const handleBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const url = URL.createObjectURL(file);
          const type = file.type.startsWith('video') ? 'video' : 'image';

          const newConfig = JSON.parse(JSON.stringify(config));
          newConfig.background.type = type;
          newConfig.background.url = url;
          onUpdate(newConfig);
      }
  };

  const handleFontUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
       const reader = new FileReader();
       reader.onload = (ev) => {
           if(ev.target?.result) {
               const fontName = 'CustomFont-' + Date.now();
               const fontFace = new FontFace(fontName, `url(${ev.target.result})`);
               fontFace.load().then((loadedFace) => {
                   document.fonts.add(loadedFace);
                   updateNested('font', 'family', fontName);
               }).catch(err => console.error("Font load failed", err));
           }
       };
       reader.readAsDataURL(file);
    }
  };

  const handleJsonChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) onJsonUpload(event.target.result as string);
    };
    reader.readAsText(file);
  };

  const handleSrtChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) onSrtUpload(event.target.result as string);
    };
    reader.readAsText(file);
  };

  const handleAudioChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        onAudioLayerAdd(file);
        // Reset input
        if (audioInputRef.current) audioInputRef.current.value = '';
    }
  };

  // Keyframe Logic
  const addKeyframe = () => {
    const newKeyframe: AnimationKeyframe = {
      id: Date.now().toString(),
      time: currentTime,
      values: {
        colors_active: config.colors.active,
        colors_text: config.colors.text,
        background_color: config.background.color,
        effects_glow: config.effects.glow,
        camera_zoom: 0,
        camera_rotate: 0,
        image_effects: config.background.imageEffects || [],
        image_effect_speed: config.background.imageEffectSpeed || 1.0
      }
    };
    const newConfig = { ...config, keyframes: [...(config.keyframes || []), newKeyframe].sort((a, b) => a.time - b.time) };
    onUpdate(newConfig);
    setSelectedKeyframeId(newKeyframe.id);
  };

  const updateKeyframe = (id: string, updates: Partial<AnimationKeyframe> | Partial<AnimationKeyframe['values']>) => {
     let newConfig = { ...config };
     newConfig.keyframes = newConfig.keyframes.map(kf => {
         if (kf.id === id) {
             if ('values' in updates) {
                 return { ...kf, values: { ...kf.values, ...(updates as any).values } };
             } else {
                 return { ...kf, ...updates };
             }
         }
         return kf;
     });

     if ('time' in updates) {
         newConfig.keyframes.sort((a, b) => a.time - b.time);
     }
     onUpdate(newConfig);
  };

  const deleteKeyframe = (id: string) => {
    const newConfig = { ...config };
    newConfig.keyframes = newConfig.keyframes.filter(kf => kf.id !== id);
    onUpdate(newConfig);
    if(selectedKeyframeId === id) setSelectedKeyframeId(null);
  }

  const selectedKeyframe = config.keyframes?.find(k => k.id === selectedKeyframeId);

  return (
    <div className="h-full flex flex-col bg-neutral-800 border-r border-white/5 text-gray-200">

      {/* Tab Navigation */}
      <div className="flex border-b border-white/5 bg-neutral-900 overflow-x-auto no-scrollbar">
        <button 
          onClick={() => setActiveTab('project')}
          title="Project Files"
          className={`flex-1 min-w-[60px] py-4 text-xs font-bold flex flex-col items-center justify-center gap-1 transition-colors border-b-2 ${activeTab === 'project' ? 'text-cyan-400 border-cyan-400 bg-white/5' : 'text-gray-500 hover:text-gray-300 border-transparent'}`}
        >
          <FolderOpen size={16} />
          Files
        </button>
        <button 
          onClick={() => setActiveTab('lyrics')}
          title="Edit Lyrics"
          className={`flex-1 min-w-[60px] py-4 text-xs font-bold flex flex-col items-center justify-center gap-1 transition-colors border-b-2 ${activeTab === 'lyrics' ? 'text-cyan-400 border-cyan-400 bg-white/5' : 'text-gray-500 hover:text-gray-300 border-transparent'}`}
        >
          <AlignLeft size={16} />
          Lyrics
        </button>
        <button 
          onClick={() => setActiveTab('sections')}
          title="Sections"
          className={`flex-1 min-w-[60px] py-4 text-xs font-bold flex flex-col items-center justify-center gap-1 transition-colors border-b-2 ${activeTab === 'sections' ? 'text-cyan-400 border-cyan-400 bg-white/5' : 'text-gray-500 hover:text-gray-300 border-transparent'}`}
        >
          <Tags size={16} />
          Parts
        </button>
        <button 
          onClick={() => setActiveTab('templates')}
          title="Templates"
          className={`flex-1 min-w-[60px] py-4 text-xs font-bold flex flex-col items-center justify-center gap-1 transition-colors border-b-2 ${activeTab === 'templates' ? 'text-cyan-400 border-cyan-400 bg-white/5' : 'text-gray-500 hover:text-gray-300 border-transparent'}`}
        >
          <LayoutTemplate size={16} />
          Presets
        </button>
        <button 
          onClick={() => setActiveTab('customize')}
          title="Customize"
          className={`flex-1 min-w-[60px] py-4 text-xs font-bold flex flex-col items-center justify-center gap-1 transition-colors border-b-2 ${activeTab === 'customize' ? 'text-cyan-400 border-cyan-400 bg-white/5' : 'text-gray-500 hover:text-gray-300 border-transparent'}`}
        >
          <Sliders size={16} />
          Style
        </button>
        <button 
          onClick={() => setActiveTab('timeline')}
          title="Keyframes"
          className={`flex-1 min-w-[60px] py-4 text-xs font-bold flex flex-col items-center justify-center gap-1 transition-colors border-b-2 ${activeTab === 'timeline' ? 'text-cyan-400 border-cyan-400 bg-white/5' : 'text-gray-500 hover:text-gray-300 border-transparent'}`}
        >
          <Clock size={16} />
          Keys
        </button>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto custom-scrollbar bg-neutral-800">

        {/* PROJECT TAB */}
        {activeTab === 'project' && (
             <div className="p-4 space-y-6">

                {/* Audio Mixer */}
                <section>
                    <div className="flex items-center justify-between mb-3">
                         <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest flex items-center gap-2">
                            <Layers size={14}/> Audio Mixer
                        </h3>
                        <button
                             onClick={() => audioInputRef.current?.click()}
                             className="text-[10px] bg-neutral-700 hover:bg-neutral-600 px-2 py-1 rounded flex items-center gap-1 transition-colors"
                        >
                            <Plus size={10} /> Add Layer
                        </button>
                        <input
                            type="file"
                            ref={audioInputRef}
                            onChange={handleAudioChange}
                            accept="audio/*"
                            className="hidden"
                        />
                    </div>

                    <div className="space-y-2">
                        {audioLayers.length === 0 ? (
                            <div className="text-center p-4 border border-dashed border-white/10 rounded-lg text-xs text-gray-500">
                                No audio tracks loaded.
                            </div>
                        ) : (
                            audioLayers.map(layer => (
                                <div key={layer.id} className="bg-neutral-900 border border-white/5 rounded-lg p-2.5">
                                    <div className="flex items-center justify-between mb-2">
                                        <div className="flex items-center gap-2 overflow-hidden">
                                            <Music size={12} className="text-cyan-500 shrink-0"/>
                                            <span className="text-xs font-bold truncate text-gray-300" title={layer.name}>{layer.name}</span>
                                        </div>
                                        <button 
                                            onClick={() => onRemoveLayer(layer.id)}
                                            className="text-neutral-500 hover:text-red-400 transition-colors"
                                        >
                                            <Trash2 size={12}/>
                                        </button>
                                    </div>

                                    <div className="flex items-center gap-2">
                                        <input 
                                            type="range" min="0" max="1" step="0.01"
                                            value={layer.volume}
                                            onChange={(e) => onUpdateLayer(layer.id, { volume: parseFloat(e.target.value) })}
                                            className="flex-1 h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                                            title={`Volume: ${Math.round(layer.volume * 100)}%`}
                                        />
                                        <div className="flex items-center gap-1 shrink-0">
                                            <button
                                                onClick={() => onUpdateLayer(layer.id, { muted: !layer.muted })}
                                                className={`w-6 h-6 rounded flex items-center justify-center text-[10px] font-bold border transition-colors ${layer.muted ? 'bg-red-900/50 border-red-500/50 text-red-400' : 'bg-neutral-800 border-white/5 text-gray-400 hover:text-white'}`}
                                                title="Mute"
                                            >
                                                M
                                            </button>
                                            <button
                                                onClick={() => onUpdateLayer(layer.id, { solo: !layer.solo })}
                                                className={`w-6 h-6 rounded flex items-center justify-center text-[10px] font-bold border transition-colors ${layer.solo ? 'bg-yellow-900/50 border-yellow-500/50 text-yellow-400' : 'bg-neutral-800 border-white/5 text-gray-400 hover:text-white'}`}
                                                title="Solo"
                                            >
                                                S
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </section>

                <section>
                    <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                        <Type size={14}/> Lyrics Source
                    </h3>
                    <div className="grid grid-cols-2 gap-3">
                         <button
                            onClick={() => jsonInputRef.current?.click()}
                            className="flex flex-col items-center justify-center gap-2 p-4 bg-neutral-900 hover:bg-neutral-700 rounded-lg border border-white/5 transition-colors group"
                        >
                            <FileJson size={24} className="text-gray-500 group-hover:text-purple-400" />
                            <span className="text-xs font-bold text-gray-400 group-hover:text-white">Import JSON</span>
                        </button>
                        <input
                            type="file"
                            ref={jsonInputRef}
                            onChange={handleJsonChange}
                            accept=".json,application/json"
                            className="hidden"
                        />

                         <button
                            onClick={() => srtInputRef.current?.click()}
                            className="flex flex-col items-center justify-center gap-2 p-4 bg-neutral-900 hover:bg-neutral-700 rounded-lg border border-white/5 transition-colors group"
                        >
                            <FileText size={24} className="text-gray-500 group-hover:text-orange-400" />
                            <span className="text-xs font-bold text-gray-400 group-hover:text-white">Import SRT</span>
                        </button>
                        <input
                            type="file"
                            ref={srtInputRef}
                            onChange={handleSrtChange}
                            accept=".srt"
                            className="hidden"
                        />
                    </div>
                    <p className="text-[10px] text-gray-500 mt-2 text-center">
                        Go to "Lyrics" tab to edit imported data.
                    </p>
                </section>

                <section>
                    <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                         <ImageIcon size={14}/> Assets
                    </h3>
                    <div className="space-y-2">
                         <button 
                            onClick={() => bgInputRef.current?.click()}
                            className="w-full flex items-center justify-start gap-3 px-3 py-2 bg-neutral-900 hover:bg-neutral-700 rounded-lg border border-white/5 transition-colors text-sm text-gray-300"
                        >
                            <Upload size={16} className="text-gray-500"/>
                            Upload Background Media
                        </button>
                        <input type="file" ref={bgInputRef} onChange={handleBgUpload} accept="image/*,video/*" className="hidden"/>

                        <button 
                            onClick={() => fontInputRef.current?.click()}
                            className="w-full flex items-center justify-start gap-3 px-3 py-2 bg-neutral-900 hover:bg-neutral-700 rounded-lg border border-white/5 transition-colors text-sm text-gray-300"
                        >
                             <Type size={16} className="text-gray-500"/>
                             Upload Custom Font
                        </button>
                        <input type="file" ref={fontInputRef} onChange={handleFontUpload} accept=".ttf,.woff,.woff2,.otf" className="hidden"/>
                    </div>
                </section>

                <section className="pt-4 border-t border-white/5">
                    <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                         <RotateCcw size={14}/> Reset
                    </h3>
                    <button
                        onClick={onResetProject}
                        className="w-full flex items-center justify-center gap-2 px-3 py-2 bg-red-950/30 hover:bg-red-900/50 text-red-400 rounded-lg border border-red-900/50 transition-colors text-sm font-bold"
                    >
                        <Trash2 size={16} />
                        Reset Project Defaults
                    </button>
                </section>
             </div>
        )}

        {/* LYRICS TAB */}
        {activeTab === 'lyrics' && (
            <TimelineEditor 
                data={data} 
                onUpdate={onUpdateData} 
                currentTime={currentTime}
                onSeek={onSeek}
            />
        )}

        {/* SECTIONS TAB */}
        {activeTab === 'sections' && (
            <div className="p-4 space-y-6">
                 {['verse', 'chorus', 'bridge', 'intro', 'outro'].map((sectionKey) => {
                     const key = sectionKey as SectionType;
                     const style = config.sectionStyles?.[key] || { enabled: false };

                     return (
                         <div key={key} className="bg-neutral-900 border border-white/5 rounded-lg p-3">
                             <div className="flex items-center justify-between mb-3 border-b border-white/5 pb-2">
                                 <h3 className="text-xs font-bold text-gray-200 uppercase tracking-widest">{key}</h3>
                                 <ToggleInput 
                                    label=""
                                    value={style.enabled} 
                                    onChange={(v) => updateSectionStyle(key, 'enabled', v)}
                                 />
                             </div>

                             {style.enabled ? (
                                 <div className="space-y-3">
                                     <ColorInput 
                                        label="Active Color" 
                                        value={style.colors_active || config.colors.active} 
                                        onChange={(v) => updateSectionStyle(key, 'colors_active', v)} 
                                    />
                                     <ColorInput 
                                        label="Text Color Override" 
                                        value={style.colors_text || config.colors.text} 
                                        onChange={(v) => updateSectionStyle(key, 'colors_text', v)} 
                                    />

                                    <div>
                                        <div className="flex justify-between text-xs text-gray-400 mb-1">
                                            <span>Glow Boost</span>
                                            <span>+{((style.effects_glow_boost || 0) * 100).toFixed(0)}%</span>
                                        </div>
                                        <input 
                                            type="range" min="0" max="1" step="0.1" 
                                            value={style.effects_glow_boost || 0} 
                                            onChange={(e) => updateSectionStyle(key, 'effects_glow_boost', parseFloat(e.target.value))}
                                            className="w-full h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                                        />
                                    </div>

                                    <div>
                                        <div className="flex justify-between text-xs text-gray-400 mb-1">
                                            <span>Zoom Boost</span>
                                            <span>+{((style.camera_zoom_boost || 0) * 100).toFixed(0)}%</span>
                                        </div>
                                        <input 
                                            type="range" min="0" max="0.5" step="0.05" 
                                            value={style.camera_zoom_boost || 0} 
                                            onChange={(e) => updateSectionStyle(key, 'camera_zoom_boost', parseFloat(e.target.value))}
                                            className="w-full h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                                        />
                                    </div>

                                    {/* Animation Overrides */}
                                    <div className="pt-2 border-t border-white/5 space-y-2">
                                        <h4 className="text-[10px] font-bold text-gray-500 uppercase">Animation Override</h4>
                                        <SelectInput 
                                            label="Entrance" 
                                            value={style.animation?.entrance || config.animation.entrance} 
                                            options={['random', 'fade', 'slide', 'slam', 'zoom', 'typewriter', 'spin', 'blur', 'glitch', 'elastic', 'drop', 'scramble', 'spiral', 'inflate', 'stretch', 'stack-pop']} 
                                            onChange={(v) => {
                                                const currentAnim = style.animation || {};
                                                updateSectionStyle(key, 'animation', { ...currentAnim, entrance: v });
                                            }} 
                                        />
                                        <SelectInput 
                                            label="Active" 
                                            value={style.animation?.active || config.animation.active} 
                                            options={['random', 'pulse', 'jitter', 'bounce', 'neon', 'wave', 'rotate', 'skew', 'pop', 'flash', 'float', 'shiver', 'rainbow', 'heartbeat', 'swing', 'glitch-shake']} 
                                            onChange={(v) => {
                                                const currentAnim = style.animation || {};
                                                updateSectionStyle(key, 'animation', { ...currentAnim, active: v });
                                            }} 
                                        />
                                        <SelectInput 
                                            label="Exit" 
                                            value={style.animation?.exit || config.animation.exit} 
                                            options={['fade', 'slide', 'slam', 'zoom', 'blur', 'glitch', 'drop', 'spiral', 'sink', 'burn']} 
                                            onChange={(v) => {
                                                const currentAnim = style.animation || {};
                                                updateSectionStyle(key, 'animation', { ...currentAnim, exit: v });
                                            }} 
                                        />
                                    </div>
                                 </div>
                             ) : (
                                 <p className="text-[10px] text-gray-500 text-center py-2">
                                     Using default global styles.
                                 </p>
                             )}
                         </div>
                     );
                 })}
            </div>
        )}

        {/* TEMPLATES TAB */}
        {activeTab === 'templates' && (
          <div className="p-4 grid grid-cols-1 gap-3">
            {TEMPLATES.map((t) => (
              <div 
                key={t.id}
                onClick={() => handleTemplateSelect(t)}
                className={`group relative overflow-hidden rounded-lg border-2 cursor-pointer transition-all duration-200 ${config.id === t.id ? 'border-cyan-500 bg-white/5' : 'border-transparent hover:border-white/10 bg-neutral-900'}`}
              >
                <div className="p-3 relative z-10">
                  <div className="flex justify-between items-center mb-1">
                    <h3 className="font-bold text-sm text-gray-200 group-hover:text-cyan-300 transition-colors">{t.name}</h3>
                  </div>

                  <div className="flex gap-1.5 mb-2">
                       <div className="w-4 h-4 rounded-full border border-white/10 shadow-sm" style={{ background: t.background.color }} />
                       <div className="w-4 h-4 rounded-full border border-white/10 shadow-sm" style={{ background: t.colors.text }} />
                       <div className="w-4 h-4 rounded-full border border-white/10 shadow-sm" style={{ background: t.colors.active }} />
                  </div>

                  <div className="flex flex-wrap gap-1.5">
                      <span className="text-[9px] uppercase font-bold px-1.5 py-0.5 bg-neutral-800 rounded text-gray-500">{t.animation.active}</span>
                      <span className="text-[9px] uppercase font-bold px-1.5 py-0.5 bg-neutral-800 rounded text-gray-500">{t.background.type}</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* CUSTOMIZE TAB */}
        {activeTab === 'customize' && (
          <div className="p-4 space-y-6">
            {/* Resolution */}
            <section>
                <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                    <Monitor size={14}/> Output Settings
                </h3>
                <div className="bg-neutral-900 p-3 rounded-lg border border-white/5">
                    <SelectInput 
                        label="Resolution / Aspect Ratio"
                        value={config.resolutionId}
                        options={RESOLUTIONS.map(r => r.id)}
                        onChange={(v) => {
                             const newConfig = { ...config, resolutionId: v };
                             onUpdate(newConfig);
                        }}
                    />
                    <div className="mt-2 text-[10px] text-gray-500 text-right">
                        {RESOLUTIONS.find(r => r.id === config.resolutionId)?.name}
                    </div>
                </div>
            </section>

            {/* Audio Reactivity */}
            <section>
              <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                <Music size={14}/> Audio Reactivity
              </h3>
              <div className="bg-neutral-900 p-3 rounded-lg border border-white/5 space-y-3">
                 <ToggleInput 
                    label="Enabled" 
                    value={config.audioReactivity.enabled} 
                    onChange={(v) => updateNested('audioReactivity', 'enabled', v)} 
                 />

                 {config.audioReactivity.enabled && (
                    <>
                        <SelectInput 
                            label="Visualizer Style" 
                            value={config.audioReactivity.visualizerStyle} 
                            options={['spectrum', 'orb', 'shockwave', 'none']} 
                            onChange={(v) => updateNested('audioReactivity', 'visualizerStyle', v)} 
                        />
                        <div className="pt-2">
                            <div className="flex justify-between text-xs text-gray-400 mb-1">
                                <span>Sensitivity</span>
                                <span>{Math.round(config.audioReactivity.sensitivity * 100)}%</span>
                            </div>
                            <input 
                                type="range" min="0.5" max="2.0" step="0.1" 
                                value={config.audioReactivity.sensitivity} 
                                onChange={(e) => updateNested('audioReactivity', 'sensitivity', parseFloat(e.target.value))}
                                className="w-full h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                            />
                        </div>
                    </>
                 )}
              </div>
            </section>

            {/* Background */}
            <section>
                <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                    <ImageIcon size={14}/> Background Config
                </h3>
                <div className="bg-neutral-900 p-3 rounded-lg border border-white/5 space-y-3">
                    <SelectInput 
                      label="Type" 
                      value={config.background.type} 
                      options={['solid', 'image', 'video', 'procedural']} 
                      onChange={(v) => updateNested('background', 'type', v)} 
                    />

                    {config.background.type === 'solid' && (
                        <ColorInput label="Color" value={config.background.color} onChange={(v) => updateNested('background', 'color', v)} />
                    )}

                    {(config.background.type === 'procedural' || config.background.type === 'image' || config.background.type === 'video') && (
                        <>
                             {config.background.type === 'procedural' ? (
                                <>
                                    <ColorInput label="Base Color" value={config.background.color} onChange={(v) => updateNested('background', 'color', v)} />
                                    <SelectInput 
                                        label="Style" 
                                        value={config.background.proceduralStyle || 'grid'} 
                                        options={['grid', 'stars', 'plasma', 'tunnel', 'matrix', 'gradient-wave', 'hexagons', 'kaleidoscope', 'dna']} 
                                        onChange={(v) => updateNested('background', 'proceduralStyle', v)} 
                                    />
                                </>
                             ) : (
                                <>
                                    <MultiToggleInput 
                                        label="Active Effects" 
                                        values={config.background.imageEffects || []} 
                                        options={['dark-error', 'red-error', 'zoom-slow', 'chromatic-shift', 'alert', 'thermal', 'vhs-stripes']} 
                                        onChange={(v) => updateNested('background', 'imageEffects', v)} 
                                    />
                                    <div className="pt-2">
                                        <div className="flex justify-between text-xs text-gray-400 mb-1">
                                            <span>Effect Speed</span>
                                            <span>{(config.background.imageEffectSpeed || 1.0).toFixed(1)}x</span>
                                        </div>
                                        <input 
                                            type="range" min="0.1" max="5.0" step="0.1" 
                                            value={config.background.imageEffectSpeed || 1.0} 
                                            onChange={(e) => updateNested('background', 'imageEffectSpeed', parseFloat(e.target.value))}
                                            className="w-full h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                                        />
                                    </div>
                                </>
                             )}

                             <div className="pt-2">
                                <div className="flex justify-between text-xs text-gray-400 mb-1">
                                    <span>
                                        {config.background.type === 'procedural' ? 'Intensity/Speed' : 'Opacity/Dim'}
                                    </span>
                                    <span>{Math.round((config.background.intensity || 0.5) * 100)}%</span>
                                </div>
                                <input 
                                    type="range" min={config.background.type === 'procedural' ? "0.1" : "0"} max={config.background.type === 'procedural' ? "2.0" : "1.0"} step="0.1" 
                                    value={config.background.intensity ?? (config.background.type === 'procedural' ? 0.5 : 1.0)} 
                                    onChange={(e) => updateNested('background', 'intensity', parseFloat(e.target.value))}
                                    className="w-full h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                                />
                             </div>

                             {config.background.type === 'video' && (
                                 <div className="pt-2">
                                    <div className="flex justify-between text-xs text-gray-400 mb-1">
                                        <span>Playback Speed</span>
                                        <span>{config.background.playbackSpeed || 1.0}x</span>
                                    </div>
                                    <input 
                                        type="range" min="0.1" max="4.0" step="0.1" 
                                        value={config.background.playbackSpeed || 1.0} 
                                        onChange={(e) => updateNested('background', 'playbackSpeed', parseFloat(e.target.value))}
                                        className="w-full h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                                    />
                                </div>
                             )}
                        </>
                    )}
                </div>
            </section>

            {/* Colors */}
            <section>
              <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                <Palette size={14}/> Palette
              </h3>
              <div className="space-y-2">
                <ColorInput label="Main Text" value={config.colors.text} onChange={(v) => updateColor('text', v)} />
                <ColorInput label="Active Word" value={config.colors.active} onChange={(v) => updateColor('active', v)} />
                <ColorInput label="Accents/Shadows" value={config.colors.secondary} onChange={(v) => updateColor('secondary', v)} />
              </div>
            </section>

            {/* Font */}
             <section>
               <div className="flex items-center justify-between mb-3 border-b border-white/5 pb-2">
                  <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest flex items-center gap-2">
                    <Type size={14}/> Typography
                  </h3>
                  <ToggleInput label="Show Lyrics" value={config.showLyrics ?? true} onChange={(v) => onUpdate({ ...config, showLyrics: v })} />
               </div>
              <div className="bg-neutral-900 p-3 rounded-lg border border-white/5 space-y-3">
                <SelectInput 
                   label="Font Family"
                   value={config.font.family}
                   options={FONTS} 
                   onChange={(v) => updateNested('font', 'family', v)}
                />

                <div className="flex gap-3">
                    <div className="flex-1">
                        <SelectInput 
                            label="Weight" 
                            value={config.font.weight} 
                            options={['100', '300', '400', '700', '900']} 
                            onChange={(v) => updateNested('font', 'weight', v)}
                        />
                    </div>
                    <div className="flex-1 pt-6">
                        <ToggleInput label="Italic" value={config.font.italic} onChange={(v) => updateNested('font', 'italic', v)}/>
                    </div>
                </div>
              </div>
            </section>

            {/* Animation */}
            <section>
              <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                <Video size={14}/> Animation Style
              </h3>
              <div className="bg-neutral-900 p-3 rounded-lg border border-white/5 space-y-3">
                <SelectInput 
                   label="In" 
                   value={config.animation.entrance} 
                   options={['random', 'fade', 'slide', 'slam', 'zoom', 'typewriter', 'spin', 'blur', 'glitch', 'elastic', 'drop', 'scramble', 'spiral', 'inflate', 'stretch', 'stack-pop']} 
                   onChange={(v) => updateNested('animation', 'entrance', v)} 
                />
                <SelectInput 
                   label="Active" 
                   value={config.animation.active} 
                   options={['random', 'pulse', 'jitter', 'bounce', 'neon', 'wave', 'rotate', 'skew', 'pop', 'flash', 'float', 'shiver', 'rainbow', 'heartbeat', 'swing', 'glitch-shake']} 
                   onChange={(v) => updateNested('animation', 'active', v)} 
                />
                <SelectInput 
                   label="Out" 
                   value={config.animation.exit} 
                   options={['fade', 'slide', 'slam', 'zoom', 'blur', 'glitch', 'drop', 'spiral', 'sink', 'burn']} 
                   onChange={(v) => updateNested('animation', 'exit', v)} 
                />
              </div>
            </section>

             {/* Camera */}
             <section>
              <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                <Camera size={14}/> Camera Movement
              </h3>
              <div className="bg-neutral-900 p-3 rounded-lg border border-white/5 grid grid-cols-2 gap-x-4 gap-y-2">
                   <ToggleInput label="Shake" value={config.camera.shake} onChange={(v) => updateNested('camera', 'shake', v)} />
                   <ToggleInput label="Zoom Beat" value={config.camera.zoomBeat} onChange={(v) => updateNested('camera', 'zoomBeat', v)} />
                   <ToggleInput label="Rotate" value={config.camera.rotate} onChange={(v) => updateNested('camera', 'rotate', v)} />
                   <ToggleInput label="Sway" value={config.camera.sway} onChange={(v) => updateNested('camera', 'sway', v)} />
                   <ToggleInput label="Hard Kick" value={config.camera.hardKick} onChange={(v) => updateNested('camera', 'hardKick', v)} />
                   <ToggleInput label="Panic" value={config.camera.panic} onChange={(v) => updateNested('camera', 'panic', v)} />
                   <ToggleInput label="Screen Pump" value={config.camera.screenPump} onChange={(v) => updateNested('camera', 'screenPump', v)} />
              </div>
            </section>

            {/* Effects */}
            <section>
              <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                <Aperture size={14}/> VFX
              </h3>
              <div className="bg-neutral-900 p-3 rounded-lg border border-white/5 space-y-3">
                 <div className="pb-2">
                    <div className="flex justify-between text-xs text-gray-400 mb-1">
                        <span>Glow</span>
                        <span>{Math.round(config.effects.glow * 100)}%</span>
                    </div>
                    <input 
                        type="range" min="0" max="1" step="0.1" 
                        value={config.effects.glow} 
                        onChange={(e) => updateNested('effects', 'glow', parseFloat(e.target.value))}
                        className="w-full h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                    />
                 </div>
                 <div className="grid grid-cols-2 gap-x-4 gap-y-2">
                    <ToggleInput label="Blur" value={config.effects.blur} onChange={(v) => updateNested('effects', 'blur', v)} />
                    <ToggleInput label="Reactive CA" value={config.effects.chromaticAberration} onChange={(v) => updateNested('effects', 'chromaticAberration', v)} />
                    <ToggleInput label="Vignette" value={config.effects.vignette} onChange={(v) => updateNested('effects', 'vignette', v)} />
                    <ToggleInput label="Scanlines" value={config.effects.scanlines} onChange={(v) => updateNested('effects', 'scanlines', v)} />
                    <ToggleInput label="CRT Noise" value={config.effects.filmGrain} onChange={(v) => updateNested('effects', 'filmGrain', v)} />
                    <ToggleInput label="Mirror" value={config.effects.mirror} onChange={(v) => updateNested('effects', 'mirror', v)} />
                    <ToggleInput label="Inv. Beat" value={config.effects.invert} onChange={(v) => updateNested('effects', 'invert', v)} />
                    <ToggleInput label="Distort" value={config.effects.barrelDistortion} onChange={(v) => updateNested('effects', 'barrelDistortion', v)} />
                    <ToggleInput label="Pixelate" value={config.effects.mosaic} onChange={(v) => updateNested('effects', 'mosaic', v)} />
                    <ToggleInput label="Sepia" value={config.effects.sepia} onChange={(v) => updateNested('effects', 'sepia', v)} />
                    <ToggleInput label="Grayscale" value={config.effects.grayscale} onChange={(v) => updateNested('effects', 'grayscale', v)} />
                    <ToggleInput label="Halftone" value={config.effects.halftone} onChange={(v) => updateNested('effects', 'halftone', v)} />
                    <ToggleInput label="Old Movie" value={config.effects.oldMovie} onChange={(v) => updateNested('effects', 'oldMovie', v)} />
                    <ToggleInput label="Kaleidoscope" value={config.effects.kaleidoscope} onChange={(v) => updateNested('effects', 'kaleidoscope', v)} />
                    <ToggleInput label="RGB Split" value={config.effects.rgbSplit} onChange={(v) => updateNested('effects', 'rgbSplit', v)} />
                 </div>
              </div>
            </section>

            {/* Particles */}
            <section>
              <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                <Grid size={14}/> Particles
              </h3>
              <div className="bg-neutral-900 p-3 rounded-lg border border-white/5 space-y-3">
                  <ToggleInput label="Enabled" value={config.particles.enabled} onChange={(v) => updateNested('particles', 'enabled', v)} />

                  {config.particles.enabled && (
                      <>
                        <SelectInput 
                            label="Shape" 
                            value={config.particles.shape} 
                            options={['circle', 'square', 'star', 'hexagon', 'triangle', 'note']} 
                            onChange={(v) => updateNested('particles', 'shape', v)} 
                        />
                        <SelectInput 
                            label="Behavior" 
                            value={config.particles.particleBehavior || 'drift'} 
                            options={['drift', 'rise']} 
                            onChange={(v) => updateNested('particles', 'particleBehavior', v)} 
                        />
                        <div className="space-y-3 pt-2">
                            <div>
                                <div className="flex justify-between text-xs text-gray-400 mb-1">
                                    <span>Count</span>
                                    <span>{config.particles.count}</span>
                                </div>
                                <input 
                                    type="range" min="0" max="300" step="10" 
                                    value={config.particles.count} 
                                    onChange={(e) => updateNested('particles', 'count', parseInt(e.target.value))}
                                    className="w-full h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                                />
                            </div>
                             <div>
                                <div className="flex justify-between text-xs text-gray-400 mb-1">
                                    <span>Speed</span>
                                    <span>{config.particles.speed.toFixed(1)}</span>
                                </div>
                                <input 
                                    type="range" min="0" max="5.0" step="0.1" 
                                    value={config.particles.speed} 
                                    onChange={(e) => updateNested('particles', 'speed', parseFloat(e.target.value))}
                                    className="w-full h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                                />
                            </div>
                        </div>
                      </>
                  )}
              </div>
            </section>
          </div>
        )}

        {/* TIMELINE TAB */}
        {activeTab === 'timeline' && (
           <div className="p-4 flex flex-col h-full">
               <button
                  onClick={addKeyframe}
                  className="mb-4 w-full flex items-center justify-center gap-2 py-3 bg-cyan-700 hover:bg-cyan-600 rounded-lg font-bold text-sm transition-all"
               >
                   <Plus size={16} /> Add Keyframe at {new Date(currentTime * 1000).toISOString().substr(14, 5)}
               </button>

               <div className="flex-1 overflow-y-auto space-y-2 mb-4">
                  {(config.keyframes || []).length === 0 ? (
                      <div className="text-center text-gray-600 text-xs mt-10">
                          No keyframes.<br/>Values are static.
                      </div>
                  ) : (
                      (config.keyframes || []).map((kf, idx) => (
                          <div 
                              key={kf.id}
                              onClick={() => setSelectedKeyframeId(kf.id)}
                              className={`p-3 rounded-lg border flex items-center justify-between cursor-pointer transition-colors ${selectedKeyframeId === kf.id ? 'bg-cyan-900/30 border-cyan-500/50' : 'bg-neutral-900 border-white/5 hover:border-white/20'}`}
                          >
                              <div className="flex flex-col">
                                  <span className="font-mono font-bold text-xs text-gray-300">Keyframe {idx + 1}</span>
                                  <span className="text-[10px] text-gray-500">{new Date(kf.time * 1000).toISOString().substr(14, 5)}s</span>
                              </div>
                          </div>
                      ))
                  )}
               </div>

               {selectedKeyframe && (
                   <KeyframeEditor 
                      keyframe={selectedKeyframe} 
                      defaults={config} 
                      onUpdate={updateKeyframe} 
                      onDelete={deleteKeyframe}
                   />
               )}
           </div>
        )}
      </div>
    </div>
  );
};

